import React, { useRef, useState, useMemo, useEffect, useCallback, useLayoutEffect } from 'react';
import { Canvas, useThree, ThreeEvent, useFrame } from '@react-three/fiber';
import { OrbitControls, Grid, TransformControls, Html, GizmoHelper, GizmoViewport, Edges, Text, Billboard, useHelper } from '@react-three/drei';
import * as THREE from 'three';
import { useApp } from '../context/AppContext';
import { ToolType, IPoint, IShape, IGuideLine } from '../types';
import { SNAP_GRID, DEFAULT_COLOR, FLAT_COLOR, HIGHLIGHT_COLOR, DEFAULT_HEIGHT } from '../constants';
import AIAssistant from './AIAssistant';

// --- Constants ---
const SNAP_THRESHOLD = 0.2;
const ALIGN_THRESHOLD = 0.3;
const AXIS_SNAP_THRESHOLD = 0.4; // Threshold for snapping to X/Z axis
const EPSILON = 1e-4;

// --- Types ---
type SnapType = 'none' | 'grid' | 'vertex' | 'midpoint' | 'edge' | 'face' | 'align' | 'endpoint';
type AlignmentLine = [THREE.Vector3, THREE.Vector3];

interface SnapResult {
    position: THREE.Vector3;
    type: SnapType;
    distance: number;
    snapObjectId?: string;
    snapEdge?: [THREE.Vector3, THREE.Vector3];
}

interface InferenceGuide {
    type: 'x' | 'z';
    start: THREE.Vector3;
    end: THREE.Vector3;
}

type PushPullMode = 'top' | 'side' | 'none';

interface PushPullState {
    mode: PushPullMode;
    hoveredShapeId: string | null;
    hoveredEdgeIndex: number;
    dragStartPoint: THREE.Vector3 | null;
    originalHeight: number;
    originalPoints: IPoint[];
    normal: THREE.Vector3;
    dragHeight?: number;
}

interface ShapeRendererProps {
    shape: IShape;
    isSelected: boolean;
    onSelect: (e: ThreeEvent<MouseEvent>) => void;
    pushPullState: PushPullState;
    pushPullHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerUp: () => void;
        handlePointerMove: (e: ThreeEvent<PointerEvent>) => void;
    };
    drawingHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerUp: (e: ThreeEvent<PointerEvent>) => void;
        handleClick: (e: ThreeEvent<MouseEvent>) => void;
    };
    setDraggingState: (isDragging: boolean) => void;
    setShapeRef: (ref: THREE.Group | null) => void; 
    shapeRefs: React.MutableRefObject<Record<string, THREE.Group | null>>;
    setAlignmentLines: (lines: AlignmentLine[]) => void;
}

// --- Geometry Helpers ---
const createThreeShape = (points: IPoint[]) => {
  const shape = new THREE.Shape();
  if (!points || points.length === 0) return shape;
  if (points[0]) {
    shape.moveTo(points[0].x, -points[0].z); 
    for (let i = 1; i < points.length; i++) {
        if (points[i]) shape.lineTo(points[i].x, -points[i].z);
    }
  }
  shape.closePath();
  return shape;
};

const createCirclePoints = (radius: number, segments = 32): IPoint[] => {
  const points: IPoint[] = [];
  for (let i = 0; i < segments; i++) {
    const theta = (i / segments) * Math.PI * 2;
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push(points[0]);
  return points;
};

const createArcPoints = (radius: number, segments = 16): IPoint[] => {
  const points: IPoint[] = [];
  points.push({ x: 0, y: 0, z: 0 });
  for (let i = 0; i <= segments; i++) {
    const theta = (i / segments) * (Math.PI / 2); 
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push({ x: 0, y: 0, z: 0 });
  return points;
};

const transformPoint = (localP: IPoint, shape: IShape): THREE.Vector3 => {
    const sX = shape.scale[0];
    const sZ = shape.scale[2];
    const rot = shape.rotation;
    const cos = Math.cos(rot);
    const sin = Math.sin(rot);
    const xScaled = localP.x * sX;
    const zScaled = localP.z * sZ;
    const xRot = xScaled * cos - zScaled * sin;
    const zRot = xScaled * sin + zScaled * cos;
    return new THREE.Vector3(xRot + shape.position[0], shape.position[1], zRot + shape.position[2]);
};

const closestPointOnSegment = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3): THREE.Vector3 => {
  const vwx = w.x - v.x;
  const vwy = w.y - v.y;
  const vwz = w.z - v.z;
  const vpx = p.x - v.x;
  const vpy = p.y - v.y;
  const vpz = p.z - v.z;
  const dot = vpx * vwx + vpy * vwy + vpz * vwz;
  const l2 = vwx * vwx + vwy * vwy + vwz * vwz;
  if (l2 === 0) return v;
  let t = dot / l2;
  t = Math.max(0, Math.min(1, t));
  return new THREE.Vector3(v.x + t * vwx, v.y + t * vwy, v.z + t * vwz);
};

const distToSegmentSquared = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3) => {
    const l2 = v.distanceToSquared(w);
    if (l2 === 0) return p.distanceToSquared(v);
    let t = ((p.x - v.x) * (w.x - v.x) + (p.z - v.z) * (w.z - v.z)) / l2;
    t = Math.max(0, Math.min(1, t));
    return (p.x - (v.x + t * (w.x - v.x)))**2 + (p.z - (v.z + t * (w.z - v.z)))**2;
};

// Segment Intersection (Strict, returns null if no intersection on segments)
const getSegmentIntersection = (p1: IPoint, p2: IPoint, p3: IPoint, p4: IPoint): IPoint | null => {
    const d = (p2.x - p1.x) * (p4.z - p3.z) - (p2.z - p1.z) * (p4.x - p3.x);
    if (Math.abs(d) < EPSILON) return null;
    const u = ((p3.x - p1.x) * (p4.z - p3.z) - (p3.z - p1.z) * (p4.x - p3.x)) / d;
    const v = ((p3.x - p1.x) * (p2.z - p1.z) - (p3.z - p1.z) * (p2.x - p1.x)) / d;

    // Check if intersection is strictly within both segments
    if (u >= EPSILON && u <= 1 - EPSILON && v >= EPSILON && v <= 1 - EPSILON) {
        return { x: p1.x + u * (p2.x - p1.x), y: 0, z: p1.z + u * (p2.z - p1.z) };
    }
    return null;
};

// --- Polygon Cutting Algorithm ---
// Cuts a polygon by a segment defined by lineStart -> lineEnd
const cutPolygonBySegment = (polyPoints: IPoint[], lineStart: IPoint, lineEnd: IPoint): [IPoint[], IPoint[]] | null => {
    interface Intersection {
        point: IPoint;
        edgeIndex: number;
        dist: number;
    }
    const intersections: Intersection[] = [];

    // Check intersection with all edges
    for (let i = 0; i < polyPoints.length; i++) {
        const p1 = polyPoints[i];
        const p2 = polyPoints[(i + 1) % polyPoints.length];
        const hit = getSegmentIntersection(p1, p2, lineStart, lineEnd);

        if (hit) {
            // Avoid duplicate intersections (e.g., hitting exactly on a vertex might register twice)
            const isDuplicate = intersections.some(
                intr => Math.abs(intr.point.x - hit.x) < 0.001 && Math.abs(intr.point.z - hit.z) < 0.001
            );
            if (!isDuplicate) {
                const dist = Math.sqrt((hit.x - lineStart.x)**2 + (hit.z - lineStart.z)**2);
                intersections.push({ point: hit, edgeIndex: i, dist });
            }
        }
    }

    // We need exactly 2 intersections (entry and exit) to split a simple convex/concave polygon effectively in this context
    if (intersections.length !== 2) return null;

    intersections.sort((a, b) => a.dist - b.dist);
    const [hit1, hit2] = intersections;

    // Construct Polygon A
    // Start at hit1, go to end of hit1's edge, continue vertices until hit2's edge, go to hit2, close to hit1
    const polyA: IPoint[] = [hit1.point];
    let idx = (hit1.edgeIndex + 1) % polyPoints.length;
    while (true) {
        // If the next vertex is beyond hit2's edge, we stop
        // Check if we just wrapped around past hit2
        // A simpler way: just iterate until we hit hit2's edge index

        polyA.push(polyPoints[idx]);

        if (idx === hit2.edgeIndex) {
            polyA.push(hit2.point);
            break;
        }
        idx = (idx + 1) % polyPoints.length;
        if (polyA.length > polyPoints.length * 2) break; // Safety
    }

    // Construct Polygon B
    // Start at hit2, go to end of hit2's edge, continue vertices until hit1's edge, go to hit1
    const polyB: IPoint[] = [hit2.point];
    idx = (hit2.edgeIndex + 1) % polyPoints.length;
    while (true) {
        polyB.push(polyPoints[idx]);
        if (idx === hit1.edgeIndex) {
            polyB.push(hit1.point);
            break;
        }
        idx = (idx + 1) % polyPoints.length;
        if (polyB.length > polyPoints.length * 2) break; // Safety
    }

    return [polyA, polyB];
};

const getLineEndpoints = (shape: IShape): [THREE.Vector3, THREE.Vector3] | null => {
    // Also consider shapes of type 'line'
    if (shape.name === 'Edge' || shape.type === 'line') {
         // If it's a line type, it should have 2 points
         if (shape.points.length >= 2) {
             // Assuming local coordinates, transform to world
             const p1 = transformPoint(shape.points[0], shape);
             const p2 = transformPoint(shape.points[1], shape);
             return [p1, p2];
         }
    }

    if (shape.name !== 'Edge') return null;

    // Fallback for legacy 'Edge' named shapes if any
    let minX = Infinity, maxX = -Infinity;
    shape.points.forEach(p => {
        if (p.x < minX) minX = p.x;
        if (p.x > maxX) maxX = p.x;
    });

    const halfLen = (maxX - minX) / 2;
    const scaledHalfLen = halfLen * shape.scale[0];

    const pos = new THREE.Vector3(shape.position[0], shape.position[1], shape.position[2]);
    const angle = -shape.rotation; 

    const dx = Math.cos(angle) * scaledHalfLen;
    const dz = Math.sin(angle) * scaledHalfLen;

    const p1 = new THREE.Vector3(pos.x - dx, pos.y, pos.z - dz);
    const p2 = new THREE.Vector3(pos.x + dx, pos.y, pos.z + dz);

    return [p1, p2];
};

const getGeometrySnap = (
    cursorPos: THREE.Vector3, 
    shapes: IShape[], 
    activePoints: IPoint[] = [],
    threshold: number,
    intersectedObject?: THREE.Intersection
): SnapResult => {
    let bestSnap: SnapResult;
    const getShapeUserData = (obj: THREE.Object3D) => {
        if (obj.userData?.isShape) return obj.userData;
        if (obj.parent?.userData?.isShape) return obj.parent.userData;
        return null;
    };
    const shapeData = intersectedObject ? getShapeUserData(intersectedObject.object) : null;
    if (intersectedObject && shapeData) {
        bestSnap = { position: intersectedObject.point, type: 'face', distance: 0, snapObjectId: shapeData.id };
    } else {
        bestSnap = {
            position: new THREE.Vector3(Math.round(cursorPos.x / SNAP_GRID) * SNAP_GRID, cursorPos.y, Math.round(cursorPos.z / SNAP_GRID) * SNAP_GRID),
            type: 'grid',
            distance: Infinity
        };
    }

    // Snap to start point of drawing for Loop Closure
    if (activePoints && activePoints.length > 0) {
        const startPt = activePoints[0];
        const ptVec = new THREE.Vector3(startPt.x, startPt.y, startPt.z);
        const dist = ptVec.distanceTo(cursorPos);
        if (dist < threshold * 2.0) return { position: ptVec, type: 'endpoint', distance: dist }; // Increased threshold for easier closure
    }

    for (const shape of shapes) {
        // Special handling for lines/edges
        if (shape.type === 'line' || shape.name === 'Edge') {
             const endpoints = getLineEndpoints(shape);
             if (endpoints) {
                 for(const ep of endpoints) {
                     if (Math.abs(ep.y - cursorPos.y) < 0.2) {
                         const dist = ep.distanceTo(cursorPos);
                         if (dist < threshold) {
                             if (bestSnap.type === 'face' || bestSnap.type === 'grid' || dist < bestSnap.distance) {
                                 bestSnap = { position: ep, type: 'endpoint', distance: dist, snapObjectId: shape.id };
                             }
                         }
                     }
                 }
                 // Check edge itself for midpoint/edge snap
                 const [v1, v2] = endpoints;
                 const mid = new THREE.Vector3().addVectors(v1, v2).multiplyScalar(0.5);
                 const distMid = mid.distanceTo(cursorPos);
                 if (distMid < threshold) {
                      if (bestSnap.type === 'face' || bestSnap.type === 'grid' || distMid < bestSnap.distance) {
                        bestSnap = { position: mid, type: 'midpoint', distance: distMid, snapObjectId: shape.id, snapEdge: [v1, v2] };
                      }
                 }
                 const projected = closestPointOnSegment(cursorPos, v1, v2);
                 const distEdge = projected.distanceTo(cursorPos);
                 if (distEdge < threshold) {
                     if (bestSnap.type === 'face' || bestSnap.type === 'grid' || distEdge < bestSnap.distance) {
                        bestSnap = { position: projected, type: 'edge', distance: distEdge, snapObjectId: shape.id, snapEdge: [v1, v2] };
                     }
                 }
                 continue; 
             }
        }

        const currentH = shape.height * shape.scale[1];
        const hasHeight = Math.abs(currentH) > 0.001;
        for (let i = 0; i < shape.points.length; i++) {
            const worldPt = transformPoint(shape.points[i], shape);
            let dist = worldPt.distanceTo(cursorPos);
            if (dist < threshold) {
                 if (bestSnap.type === 'face' || bestSnap.type === 'grid' || dist < bestSnap.distance) {
                    bestSnap = { position: worldPt, type: 'vertex', distance: dist, snapObjectId: shape.id };
                 }
            }
            if (hasHeight) {
                const worldPtTop = worldPt.clone().setY(worldPt.y + currentH);
                dist = worldPtTop.distanceTo(cursorPos);
                if (dist < threshold) {
                     if (bestSnap.type === 'face' || bestSnap.type === 'grid' || dist < bestSnap.distance) {
                        bestSnap = { position: worldPtTop, type: 'vertex', distance: dist, snapObjectId: shape.id };
                     }
                }
            }
        }
    }
    if (bestSnap.type === 'vertex' || bestSnap.type === 'endpoint') return bestSnap;
    let bestEdgeSnap: SnapResult | null = null;
    let minEdgeDist = threshold;
    for (const shape of shapes) {
        if (shape.type === 'line') continue; // Handled above

        const pts = shape.points;
        const len = pts.length;
        const currentH = shape.height * shape.scale[1];
        const hasHeight = Math.abs(currentH) > 0.001;
        for (let i = 0; i < len; i++) {
             const p1 = transformPoint(pts[i], shape);
             const p2 = transformPoint(pts[(i + 1) % len], shape);
             const checkSegment = (v1: THREE.Vector3, v2: THREE.Vector3) => {
                 const mid = new THREE.Vector3().addVectors(v1, v2).multiplyScalar(0.5);
                 const distMid = mid.distanceTo(cursorPos);
                 if (distMid < threshold && distMid < minEdgeDist) {
                     bestEdgeSnap = { position: mid, type: 'midpoint', distance: distMid, snapObjectId: shape.id, snapEdge: [v1, v2] };
                     minEdgeDist = distMid;
                     return;
                 }
                 const projected = closestPointOnSegment(cursorPos, v1, v2);
                 const distEdge = projected.distanceTo(cursorPos);
                 if (distEdge < threshold && distEdge < minEdgeDist) {
                     bestEdgeSnap = { position: projected, type: 'edge', distance: distEdge, snapObjectId: shape.id, snapEdge: [v1, v2] };
                     minEdgeDist = distEdge;
                 }
             };
             checkSegment(p1, p2);
             if (hasHeight) {
                 const p1Top = p1.clone().setY(p1.y + currentH);
                 const p2Top = p2.clone().setY(p2.y + currentH);
                 checkSegment(p1Top, p2Top);
                 checkSegment(p1, p1Top);
             }
        }
    }
    if (bestEdgeSnap) return bestEdgeSnap;
    return bestSnap;
};

// ... Components ...

const SimpleLine: React.FC<{ points: (THREE.Vector3 | [number, number, number])[], color: string, dashed?: boolean, opacity?: number, transparent?: boolean, lineWidth?: number, depthTest?: boolean }> = ({ points, color, dashed, opacity, transparent, lineWidth, depthTest = true }) => {
    const ref = useRef<THREE.Line>(null);
    const geometry = useMemo(() => {
        const pts = points.map(p => (p instanceof THREE.Vector3 ? p : new THREE.Vector3(...p)));
        return new THREE.BufferGeometry().setFromPoints(pts);
    }, [points]);

    useLayoutEffect(() => {
        if (dashed && ref.current) {
            ref.current.computeLineDistances();
        }
    }, [geometry, dashed]);

    return (
        <line ref={ref} geometry={geometry}>
            {dashed ? (
                <lineDashedMaterial color={color} dashSize={0.2} gapSize={0.1} transparent={transparent} opacity={opacity} depthTest={depthTest} toneMapped={false} />
            ) : (
                <lineBasicMaterial color={color} transparent={transparent} opacity={opacity} depthTest={depthTest} toneMapped={false} />
            )}
        </line>
    );
};

const GuideLinesRenderer: React.FC<{ lines: IGuideLine[] }> = ({ lines }) => {
    if (lines.length === 0) return null;
    return (
        <group renderOrder={9999}>
            {lines.map((line) => (
                <SimpleLine 
                    key={line.id} 
                    points={[line.points[0], line.points[1]]} 
                    color="#a855f7" // Purple
                    dashed 
                    lineWidth={1} 
                    depthTest={false} 
                    opacity={0.8} 
                />
            ))}
        </group>
    );
};

const InferenceGuideRenderer: React.FC<{ guide: InferenceGuide | null }> = ({ guide }) => {
    if (!guide) return null;
    const color = guide.type === 'x' ? '#ef4444' : '#22c55e'; // Red for X, Green for Z
    return (
         <SimpleLine 
            points={[guide.start, guide.end]} 
            color={color} 
            lineWidth={2} 
            depthTest={false} 
            opacity={0.8} 
        />
    );
};

const DimensionShape: React.FC<{ shape: IShape; isSelected: boolean; onSelect: (e: ThreeEvent<MouseEvent>) => void }> = ({ shape, isSelected, onSelect }) => {
    const { formatValue } = useApp();
    if (!shape.points || shape.points.length < 3) return null;
    const p1 = new THREE.Vector3(shape.points[0].x, shape.points[0].y, shape.points[0].z);
    const p2 = new THREE.Vector3(shape.points[1].x, shape.points[1].y, shape.points[1].z);
    const p3 = new THREE.Vector3(shape.points[2].x, shape.points[2].y, shape.points[2].z);
    const direction = new THREE.Vector3().subVectors(p2, p1).normalize();
    const length = p1.distanceTo(p2);
    const v12 = new THREE.Vector3().subVectors(p2, p1);
    const v13 = new THREE.Vector3().subVectors(p3, p1);
    const projection = v13.dot(v12) / v12.lengthSq();
    const projectedPoint = p1.clone().add(v12.multiplyScalar(projection));
    const offsetVector = new THREE.Vector3().subVectors(p3, projectedPoint);
    const dimStart = p1.clone().add(offsetVector);
    const dimEnd = p2.clone().add(offsetVector);
    const midPoint = new THREE.Vector3().addVectors(dimStart, dimEnd).multiplyScalar(0.5);
    const color = isSelected ? '#3b82f6' : '#333';
    return (
        <group onClick={(e) => { e.stopPropagation(); onSelect(e); }}>
            <SimpleLine points={[dimStart, dimEnd]} color={color} />
            <SimpleLine points={[p1, dimStart]} color="#999" dashed />
            <SimpleLine points={[p2, dimEnd]} color="#999" dashed />
            <mesh position={dimStart}><sphereGeometry args={[0.03]} /><meshBasicMaterial color={color} /></mesh>
            <mesh position={dimEnd}><sphereGeometry args={[0.03]} /><meshBasicMaterial color={color} /></mesh>
            <Billboard position={[midPoint.x, midPoint.y + 0.1, midPoint.z]}>
                <Text fontSize={0.25} color={color} anchorX="center" anchorY="middle" outlineWidth={0.03} outlineColor="#ffffff" backgroundColor="#ffffff80" padding={0.05}>{formatValue(length)}</Text>
            </Billboard>
        </group>
    );
};

const AlignmentLinesRenderer: React.FC<{ lines: AlignmentLine[] }> = ({ lines }) => {
    if (lines.length === 0) return null;
    return (
        <group>
            {lines.map((line, i) => (
                <SimpleLine key={i} points={line} color="red" dashed lineWidth={2} depthTest={false} opacity={0.8} />
            ))}
        </group>
    );
};

const SnapIndicator: React.FC<{ position: THREE.Vector3; type: SnapType; snapEdge?: [THREE.Vector3, THREE.Vector3] }> = ({ position, type, snapEdge }) => {
    if (type === 'grid') return null;
    let color = 'orange';
    if (type === 'midpoint') color = 'cyan';
    else if (type === 'vertex' || type === 'endpoint') color = '#ec4899'; 
    else if (type === 'face') color = '#3b82f6'; 
    return (
        <group position={position}>
            {type === 'face' ? (
                 <mesh rotation={[-Math.PI/2, 0, 0]}>
                    <planeGeometry args={[0.2, 0.2]} />
                    <meshBasicMaterial color={color} depthTest={false} transparent opacity={0.5} side={THREE.DoubleSide} />
                    <lineSegments><edgesGeometry args={[new THREE.PlaneGeometry(0.2, 0.2)]} /><lineBasicMaterial color={color} depthTest={false} /></lineSegments>
                 </mesh>
            ) : ( <mesh>{type !== 'edge' && <sphereGeometry args={[type === 'vertex' || type === 'endpoint' ? 0.12 : 0.05]} />}<meshBasicMaterial color={color} depthTest={false} /></mesh> )}
            {type === 'edge' && snapEdge && ( <SimpleLine points={[snapEdge[0], snapEdge[1]]} color="orange" lineWidth={3} depthTest={false} /> )}
            {type === 'midpoint' && snapEdge && ( <SimpleLine points={[snapEdge[0], snapEdge[1]]} color="cyan" lineWidth={3} depthTest={false} /> )}
        </group>
    );
};

const CursorTooltip: React.FC<{ text: string; position: THREE.Vector3; type?: SnapType }> = ({ text, position, type }) => {
    if (type === 'grid') return null;
    let displayType = '';
    switch(type) {
        case 'vertex': displayType = '頂點'; break;
        case 'midpoint': displayType = '中點'; break;
        case 'edge': displayType = '邊緣'; break;
        case 'face': displayType = '表面'; break;
        case 'endpoint': displayType = '端點'; break;
        case 'align': displayType = '對齊'; break;
        default: displayType = '';
    }
    const displayText = displayType ? (text ? `${displayType}: ${text}` : displayType) : text;
    return (
        <Html position={[position.x, position.y + 0.5, position.z]} center style={{ pointerEvents: 'none' }}>
            <div className="bg-slate-900/80 text-white text-xs px-2 py-1 rounded backdrop-blur-sm border border-slate-600 whitespace-nowrap flex items-center gap-1">
                {type && <span className={`w-2 h-2 rounded-full ${type === 'grid' ? 'bg-slate-500' : type === 'face' ? 'bg-blue-500' : 'bg-green-500'}`} />}
                {displayText}
            </div>
        </Html>
    );
};

const useShapeDrag = (
    shape: IShape,
    shapes: IShape[],
    isSelected: boolean,
    tool: ToolType,
    updateShapes: (updates: { id: string; changes: Partial<IShape> }[]) => void,
    setDraggingState: (isDragging: boolean) => void,
    selectedIds: string[],
    shapeRefs: React.MutableRefObject<Record<string, THREE.Group | null>>,
    setAlignmentLines: (lines: AlignmentLine[]) => void
) => {
    const { camera, gl } = useThree();
    const groupRef = useRef<THREE.Group>(null);
    const dragInfo = useRef({ startPoint: new THREE.Vector3(), originalPositions: {} as Record<string, THREE.Vector3>, isDragging: false });
    const getGroundIntersection = (clientX: number, clientY: number) => {
        const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
        const raycaster = new THREE.Raycaster();
        const ndc = new THREE.Vector2((clientX / gl.domElement.clientWidth) * 2 - 1, -(clientY / gl.domElement.clientHeight) * 2 + 1);
        raycaster.setFromCamera(ndc, camera);
        const target = new THREE.Vector3();
        const hit = raycaster.ray.intersectPlane(plane, target);
        return hit ? target : null;
    };
    const handlePointerMove = useCallback((e: PointerEvent) => {
        if (!dragInfo.current.isDragging) return;
        const intersect = getGroundIntersection(e.clientX, e.clientY);
        if (intersect) {
             const rawDelta = new THREE.Vector3().subVectors(intersect, dragInfo.current.startPoint);
             const myOriginalPos = dragInfo.current.originalPositions[shape.id];
             if (!myOriginalPos) return;
             const targetPos = new THREE.Vector3().addVectors(myOriginalPos, rawDelta);
             let snappedX = Math.round(targetPos.x / SNAP_GRID) * SNAP_GRID;
             let snappedZ = Math.round(targetPos.z / SNAP_GRID) * SNAP_GRID;
             const newLines: AlignmentLine[] = [];
             const snappedPos = new THREE.Vector3(snappedX, myOriginalPos.y, snappedZ);
             const effectiveDelta = new THREE.Vector3().subVectors(snappedPos, myOriginalPos);
             Object.entries(dragInfo.current.originalPositions).forEach(([id, origPos]) => {
                 const ref = shapeRefs.current[id];
                 if (ref) { ref.position.copy(origPos).add(effectiveDelta); }
             });
        }
    }, [camera, gl, shape.id, shapes, selectedIds]);
    const handlePointerUp = useCallback((e: PointerEvent) => {
        if (!dragInfo.current.isDragging) return;
        document.body.style.cursor = 'default';
        dragInfo.current.isDragging = false;
        setDraggingState(false);
        setAlignmentLines([]);
        window.removeEventListener('pointermove', handlePointerMove);
        window.removeEventListener('pointerup', handlePointerUp);
        const updates = Object.keys(dragInfo.current.originalPositions).map(id => {
            const ref = shapeRefs.current[id];
            if (ref) { return { id, changes: { position: [ref.position.x, ref.position.y, ref.position.z] as [number, number, number] } }; }
            return null;
        }).filter(Boolean) as { id: string, changes: Partial<IShape> }[];
        if (updates.length > 0) { updateShapes(updates); }
    }, [handlePointerMove, updateShapes, setDraggingState, setAlignmentLines]);
    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.SELECT || e.button !== 0) return;
        e.stopPropagation();
        const intersect = getGroundIntersection(e.clientX, e.clientY);
        if (intersect && groupRef.current) {
            dragInfo.current.isDragging = true;
            dragInfo.current.startPoint.copy(intersect);
            let idsToMove: string[] = [];
            if (isSelected) { idsToMove = [...selectedIds]; } 
            else { if (shape.groupId) { idsToMove = shapes.filter(s => s.groupId === shape.groupId).map(s => s.id); } else { idsToMove = [shape.id]; } }
            if (!idsToMove.includes(shape.id)) idsToMove.push(shape.id);
            const origins: Record<string, THREE.Vector3> = {};
            idsToMove.forEach(id => { const ref = shapeRefs.current[id]; if (ref) { origins[id] = ref.position.clone(); } });
            dragInfo.current.originalPositions = origins;
            document.body.style.cursor = 'move';
            setDraggingState(true);
            window.addEventListener('pointermove', handlePointerMove);
            window.addEventListener('pointerup', handlePointerUp);
        }
    }, [tool, shape, shapes, camera, gl, handlePointerMove, handlePointerUp, setDraggingState, isSelected, selectedIds]);
    useEffect(() => { return () => { window.removeEventListener('pointermove', handlePointerMove); window.removeEventListener('pointerup', handlePointerUp); }; }, [handlePointerMove, handlePointerUp]);
    return { groupRef, handlePointerDown };
};

const ShapeRenderer = React.memo(({ shape, isSelected, onSelect, pushPullState, pushPullHandlers, drawingHandlers, setDraggingState, setShapeRef, shapeRefs, setAlignmentLines }: ShapeRendererProps & { shapeRefs: React.MutableRefObject<Record<string, THREE.Group | null>>, setAlignmentLines: (lines: AlignmentLine[]) => void }) => {
    const { unit, tool, updateShapes, layers, selectedIds, shapes } = useApp();
    const parentLayer = layers.find(l => l.id === shape.layerId);
    if (parentLayer && !parentLayer.visible) return null;
    if (shape.type === 'dimension') { return ( <DimensionShape shape={shape} isSelected={isSelected} onSelect={(e) => { if (!isSelected) onSelect(e); }} /> ); }

    // --- Line Rendering ---
    if (shape.type === 'line') {
         if (shape.points.length < 2) return null;
         const p1 = new THREE.Vector3(shape.points[0].x, shape.points[0].y, shape.points[0].z);
         const p2 = new THREE.Vector3(shape.points[1].x, shape.points[1].y, shape.points[1].z);
         return (
             <group 
                position={[shape.position[0], shape.position[1], shape.position[2]]}
                onClick={(e) => { e.stopPropagation(); onSelect(e); }}
             >
                <SimpleLine points={[p1, p2]} color={isSelected ? '#3b82f6' : 'black'} lineWidth={2} />
             </group>
         );
    }

    const isPushPullMode = tool === ToolType.PUSH_PULL;
    const highlightColor = isPushPullMode ? shape.color : (isSelected ? HIGHLIGHT_COLOR : shape.color);
    const { groupRef, handlePointerDown } = useShapeDrag(shape, shapes, isSelected, tool, updateShapes, setDraggingState, selectedIds, shapeRefs, setAlignmentLines);
    useLayoutEffect(() => { setShapeRef(groupRef.current); return () => setShapeRef(null); }, [setShapeRef, shape.id]);
    const isDraggingTop = pushPullState.mode === 'top' && pushPullState.hoveredShapeId === shape.id && !!pushPullState.dragStartPoint;
    let scaleY = 1;
    if (isDraggingTop && pushPullState.dragHeight !== undefined && shape.height > 0) { scaleY = pushPullState.dragHeight / shape.height; }
    const shape2D = useMemo(() => createThreeShape(shape.points), [shape.points]);
    return (
        <group 
            ref={groupRef}
            position={[shape.position[0], shape.position[1], shape.position[2]]} 
            rotation={[0, shape.rotation, 0]} 
            scale={[shape.scale[0], shape.scale[1] * scaleY, shape.scale[2]]} 
            userData={{ isShape: true, id: shape.id, isContainer: true }} 
            name="shape_group" 
            onPointerDown={(e) => { if (isPushPullMode) { pushPullHandlers.handlePointerDown(e); } else if (tool === ToolType.SELECT) { if (!isSelected) { onSelect(e); } handlePointerDown(e); } else { drawingHandlers.handlePointerDown(e); } }}
            onPointerMove={(e) => { if (isPushPullMode) { pushPullHandlers.handlePointerMove(e); } }}
            onPointerUp={(e) => { if (isPushPullMode) { pushPullHandlers.handlePointerUp(); } else { drawingHandlers.handlePointerUp(e); } }}
            onClick={(e) => { if (!isPushPullMode && tool !== ToolType.SELECT) { drawingHandlers.handleClick(e); } }}
        >
            <mesh rotation={[-Math.PI/2, 0, 0]} castShadow receiveShadow userData={{ isShape: true, id: shape.id }}>
                <extrudeGeometry args={[shape2D, { depth: shape.height, bevelEnabled: false }]} />
                <meshStandardMaterial color={highlightColor} transparent={shape.type === 'flat'} opacity={shape.type === 'flat' ? 0.6 : 1.0} polygonOffset={shape.type === 'flat'} polygonOffsetFactor={shape.type === 'flat' ? -1 : 0} />
                <Edges color="#333" threshold={15} renderOrder={1000} visible={!isPushPullMode} />
            </mesh>
        </group>
    );
});

