const DrawingPreview: React.FC<{ tool: ToolType; points: IPoint[]; cursorPos: THREE.Vector3; guideCreating: { active: boolean, start: THREE.Vector3, current: THREE.Vector3, edge: [THREE.Vector3, THREE.Vector3] | null } }> = ({ tool, points, cursorPos, guideCreating }) => {
    const { formatValue } = useApp();
    const currentPoint = cursorPos;

    if (tool === ToolType.MEASURE && guideCreating.active && guideCreating.edge) {
        // Draw the temporary guide line being dragged
        const p1 = guideCreating.edge[0];
        const p2 = guideCreating.edge[1];
        const direction = new THREE.Vector3().subVectors(p2, p1).normalize();

        // Use a long length for preview
        const lineStart = guideCreating.current.clone().sub(direction.clone().multiplyScalar(100));
        const lineEnd = guideCreating.current.clone().add(direction.clone().multiplyScalar(100));

        const edgeVec = new THREE.Vector3().subVectors(p2, p1);
        const pointVec = new THREE.Vector3().subVectors(guideCreating.current, p1);
        const projected = p1.clone().add(edgeVec.clone().multiplyScalar(pointVec.dot(edgeVec) / edgeVec.lengthSq()));
        const dist = guideCreating.current.distanceTo(projected);

        return (
            <group>
                <SimpleLine points={[lineStart, lineEnd]} color="#a855f7" dashed opacity={0.6} />
                <Billboard position={[guideCreating.current.x, guideCreating.current.y + 0.2, guideCreating.current.z]}>
                    <Text fontSize={0.25} color="#a855f7" anchorX="center" anchorY="middle" outlineWidth={0.03} outlineColor="#fff" backgroundColor="#ffffff80" padding={0.05}>{formatValue(dist)}</Text>
                </Billboard>
            </group>
        );
    }

    if (points.length === 0) return null;
    const startPoint = points[points.length - 1]; // Use last point for continuous drawing

    const startVec = new THREE.Vector3(startPoint.x, startPoint.y, startPoint.z);

    if (tool === ToolType.DRAW_LINE) {
        // Just show the line from the LAST point to the cursor
        return <SimpleLine points={[startVec, currentPoint]} color="black" dashed />;
    }

    if (tool === ToolType.DRAW_RECT) {
        // Rect always uses points[0] as anchor
        const anchor = points[0];
        const p1 = new THREE.Vector3(anchor.x, anchor.y, anchor.z);
        const p2 = currentPoint;
        const minX = Math.min(p1.x, p2.x);
        const maxX = Math.max(p1.x, p2.x);
        const minZ = Math.min(p1.z, p2.z);
        const maxZ = Math.max(p1.z, p2.z);
        const rectPoints = [ new THREE.Vector3(minX, 0, minZ), new THREE.Vector3(maxX, 0, minZ), new THREE.Vector3(maxX, 0, maxZ), new THREE.Vector3(minX, 0, maxZ), new THREE.Vector3(minX, 0, minZ) ];
        return <SimpleLine points={rectPoints} color="black" dashed />;
    }

    if (tool === ToolType.DRAW_CIRCLE) {
        const radius = startVec.distanceTo(currentPoint);
        if (radius < 0.01) return null;
        const circlePoints = createCirclePoints(radius).map(p => new THREE.Vector3(p.x + startPoint.x, 0, p.z + startPoint.z));
        return ( <><SimpleLine points={circlePoints} color="black" dashed /><SimpleLine points={[startVec, currentPoint]} color="gray" dashed opacity={0.5} /></>);
    }

    if (tool === ToolType.DRAW_ARC) {
        const radius = startVec.distanceTo(currentPoint);
        if (radius < 0.01) return null;
        const arcPoints = createArcPoints(radius).map(p => new THREE.Vector3(p.x + startPoint.x, 0, p.z + startPoint.z));
         return ( <><SimpleLine points={arcPoints} color="black" dashed /><SimpleLine points={[startVec, currentPoint]} color="gray" dashed opacity={0.5} /></>);
    }

    if (tool === ToolType.MEASURE) {
        if (points.length === 1) {
            return ( <><SimpleLine points={[startVec, currentPoint]} color="blue" dashed /><mesh position={startVec}><sphereGeometry args={[0.05]} /><meshBasicMaterial color="blue" /></mesh><mesh position={currentPoint}><sphereGeometry args={[0.05]} /><meshBasicMaterial color="blue" /></mesh></> );
        } else if (points.length === 2) {
            const p2 = new THREE.Vector3(points[1].x, points[1].y, points[1].z);
            const v12 = new THREE.Vector3().subVectors(p2, startVec);
            const v13 = new THREE.Vector3().subVectors(currentPoint, startVec);
            const projection = v13.dot(v12) / v12.lengthSq();
            const projectedPoint = startVec.clone().add(v12.multiplyScalar(projection));
            const offsetVector = new THREE.Vector3().subVectors(currentPoint, projectedPoint);
            const dimStart = startVec.clone().add(offsetVector);
            const dimEnd = p2.clone().add(offsetVector);
            const midPoint = new THREE.Vector3().addVectors(dimStart, dimEnd).multiplyScalar(0.5);
            return ( <group><SimpleLine points={[dimStart, dimEnd]} color="blue" /><SimpleLine points={[startVec, dimStart]} color="gray" dashed /><SimpleLine points={[p2, dimEnd]} color="gray" dashed /><Billboard position={[midPoint.x, midPoint.y + 0.1, midPoint.z]}><Text fontSize={0.25} color="blue" anchorX="center" anchorY="middle" outlineWidth={0.03} outlineColor="#fff" backgroundColor="#ffffff80" padding={0.05}>{formatValue(startVec.distanceTo(p2))}</Text></Billboard></group>);
        }
    }
    return null;
};

const InteractionLayer: React.FC<{
    shapes: IShape[];
    tool: ToolType;
    setCursorPos: (v: THREE.Vector3) => void;
    setSnapInfo: (s: SnapResult | null) => void;
    cursorPos: THREE.Vector3;
    snapInfo: SnapResult | null;
    drawPoints: IPoint[];
    isDragging: boolean;
    drawingHeight: number;
    typedInput: string;
    guideCreating: any;
    inferenceGuide: InferenceGuide | null;
    drawingHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerUp: (e: ThreeEvent<PointerEvent>) => void;
        handleClick: (e: ThreeEvent<MouseEvent>) => void;
    };
    setInferenceGuide: (g: InferenceGuide | null) => void;
}> = ({ shapes, tool, setCursorPos, setSnapInfo, cursorPos, snapInfo, drawPoints, isDragging, drawingHeight, typedInput, guideCreating, drawingHandlers, inferenceGuide, setInferenceGuide }) => {
    const { camera, scene } = useThree();
    const { setMeasurement, formatValue, layers } = useApp();

    const updateMeasurement = useCallback((pos: THREE.Vector3, input?: string) => {
        let text = '';
        if (guideCreating.active) {
             const p1 = guideCreating.edge[0];
             const p2 = guideCreating.edge[1];
             const edgeVec = new THREE.Vector3().subVectors(p2, p1);
             const pointVec = new THREE.Vector3().subVectors(pos, p1);
             const projected = p1.clone().add(edgeVec.clone().multiplyScalar(pointVec.dot(edgeVec) / edgeVec.lengthSq()));
             const dist = pos.distanceTo(projected);
             text = `偏移距離: ${input ? input : formatValue(dist)}`;
        } else if (drawPoints.length > 0) {
            const start = drawPoints[drawPoints.length - 1]; 
            const current = pos;
            const dist = Math.sqrt((current.x - start.x)**2 + (current.y - start.y)**2 + (current.z - start.z)**2);
            if (tool === ToolType.DRAW_LINE) { text = `長度: ${input ? input : formatValue(dist)}`; } 
            else if (tool === ToolType.DRAW_RECT) {
                if (input) { text = `寬度, 深度: ${input}`; } 
                else { const w = Math.abs(current.x - start.x); const d = Math.abs(current.z - start.z); text = `寬度: ${formatValue(w)}, 深度: ${formatValue(d)}`; }
            } else if (tool === ToolType.DRAW_CIRCLE) { text = `半徑: ${input ? input : formatValue(dist)}`; } 
            else if (tool === ToolType.DRAW_ARC) { text = `半徑: ${input ? input : formatValue(dist)}`; } 
            else if (tool === ToolType.MEASURE) { text = `距離: ${input ? input : formatValue(dist)}`; }
        } else {
             if ([ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE, ToolType.DRAW_ARC, ToolType.MEASURE].includes(tool)) {
                 text = `起點: X ${formatValue(pos.x)}, Z ${formatValue(pos.z)}`;
             }
        }
        if (input !== undefined) { text += '|'; }
        setMeasurement(text);
    }, [drawPoints, tool, formatValue, setMeasurement, guideCreating]);

    useEffect(() => { if (typedInput) { updateMeasurement(cursorPos, typedInput); } }, [typedInput, cursorPos, updateMeasurement]);

    const onPointerMove = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;
        const intersectPoint = e.point; 
        const shapeIntersections = e.intersections.filter(i => (i.object.userData?.isShape || i.object.parent?.userData?.isShape) && i.object !== e.object);
        const visibleIntersections = shapeIntersections.filter(i => {
            const obj = i.object;
            const shapeId = obj.userData?.id || obj.parent?.userData?.id;
            const shape = shapes.find(s => s.id === shapeId);
            if (!shape) return false;
            const layer = layers.find(l => l.id === shape.layerId);
            return layer ? layer.visible : true;
        });
        const topShapeIntersect = visibleIntersections.length > 0 ? visibleIntersections[0] : undefined;
        const visibleShapes = shapes.filter(s => {
             const layer = layers.find(l => l.id === s.layerId);
             return layer ? layer.visible : true;
        });

        let snap = getGeometrySnap(intersectPoint, visibleShapes, drawPoints, SNAP_THRESHOLD, topShapeIntersect);
        let newInferenceGuide: InferenceGuide | null = null;

        // Axis Inference logic
        if (tool === ToolType.DRAW_LINE && drawPoints.length > 0 && (snap.type === 'grid' || snap.type === 'none')) {
            const lastPt = drawPoints[drawPoints.length - 1];
            const currentX = snap.position.x;
            const currentZ = snap.position.z;
            const diffX = Math.abs(currentX - lastPt.x);
            const diffZ = Math.abs(currentZ - lastPt.z);

            if (diffX < AXIS_SNAP_THRESHOLD) {
                 snap.position.x = lastPt.x;
                 newInferenceGuide = { type: 'z', start: new THREE.Vector3(lastPt.x, 0, lastPt.z), end: new THREE.Vector3(lastPt.x, 0, currentZ) };
                 snap.type = 'align';
            } else if (diffZ < AXIS_SNAP_THRESHOLD) {
                 snap.position.z = lastPt.z;
                 newInferenceGuide = { type: 'x', start: new THREE.Vector3(lastPt.x, 0, lastPt.z), end: new THREE.Vector3(currentX, 0, lastPt.z) };
                 snap.type = 'align';
            }
        }

        setInferenceGuide(newInferenceGuide);
        setCursorPos(snap.position);
        setSnapInfo(snap);
        if (!typedInput) { updateMeasurement(snap.position); }
    }, [tool, shapes, layers, drawPoints, setCursorPos, setSnapInfo, updateMeasurement, typedInput, setInferenceGuide]);

    if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return null;

    return (
        <group>
            <mesh 
                rotation={[-Math.PI / 2, 0, 0]} 
                position={[0, 0.005, 0]} 
                onPointerMove={onPointerMove}
                onPointerDown={drawingHandlers.handlePointerDown}
                onPointerUp={drawingHandlers.handlePointerUp}
                onClick={drawingHandlers.handleClick}
            >
                <planeGeometry args={[1000, 1000]} />
                <meshBasicMaterial visible={false} />
            </mesh>
             {snapInfo && (
                <>
                    <SnapIndicator position={snapInfo.position} type={snapInfo.type} snapEdge={snapInfo.snapEdge} />
                    <CursorTooltip text={snapInfo.type === 'none' ? '' : snapInfo.type} position={snapInfo.position} type={snapInfo.type} />
                </>
             )}
             <InferenceGuideRenderer guide={inferenceGuide} />
             {(drawPoints.length > 0 || guideCreating.active) && (
                <DrawingPreview tool={tool} points={drawPoints} cursorPos={cursorPos} guideCreating={guideCreating} />
             )}
        </group>
    );
};

const useDrawingManager = () => {
    const { tool, setTool, addShape, addGuideLine, layers, activeLayerId, replaceShapes, shapes, setMeasurement, removeShape } = useApp();
    const [drawPoints, setDrawPoints] = useState<IPoint[]>([]);
    const [cursorPos, setCursorPos] = useState(new THREE.Vector3());
    const [snapInfo, setSnapInfo] = useState<SnapResult | null>(null);
    const [isDragging, setIsDragging] = useState(false);
    const [typedInput, setTypedInput] = useState('');
    const [guideCreating, setGuideCreating] = useState<{ active: boolean, start: THREE.Vector3, current: THREE.Vector3, edge: [THREE.Vector3, THREE.Vector3] | null }>({ active: false, start: new THREE.Vector3(), current: new THREE.Vector3(), edge: null });
    const [inferenceGuide, setInferenceGuide] = useState<InferenceGuide | null>(null);
    const currentChainIds = useRef<string[]>([]);

    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Backspace') {
                setTypedInput(prev => prev.slice(0, -1));
            } else if (e.key === 'Enter') {
                handleInputCommit();
            } else if (/^[0-9.,]$/.test(e.key)) {
                setTypedInput(prev => prev + e.key);
            } else if (e.key === 'Escape') {
                if (drawPoints.length > 0) {
                    // Cancel current drawing session
                    // Remove all temporary line segments created in this chain
                    currentChainIds.current.forEach(id => removeShape(id));
                    currentChainIds.current = [];
                    setDrawPoints([]); 
                    setMeasurement('取消繪製');
                } else {
                    setTool(ToolType.SELECT); // Switch to Select tool if nothing to clear
                    setMeasurement('');
                }
            }
        };
        const handleInputCommit = () => {
            if (!typedInput) return;
            setTypedInput('');
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [typedInput, drawPoints, setTool, setMeasurement, removeShape]);

    const addPoint = (point: THREE.Vector3) => {
         const newPoint: IPoint = { x: point.x, y: point.y, z: point.z };

         if (tool === ToolType.DRAW_LINE) {

             // 1. Check for Loop Closure (snapping to start of chain)
             if (drawPoints.length > 0) {
                 const start = drawPoints[0];
                 const dist = new THREE.Vector3(newPoint.x, newPoint.y, newPoint.z)
                    .distanceTo(new THREE.Vector3(start.x, start.y, start.z));

                 // If we clicked close to the start point, close the loop
                 if (dist < SNAP_THRESHOLD) {
                     // Create the Face from all accumulated points
                     finishShape(drawPoints, 'Face');

                     // Remove the individual segments we drew along the way
                     // so we don't have duplicate edges z-fighting with the new face
                     currentChainIds.current.forEach(id => removeShape(id));
                     currentChainIds.current = [];
                     return;
                 }
             }

             // 2. Add point to local state
             setDrawPoints(prev => [...prev, newPoint]);

             // 3. Create a persistent "Line" shape for the new segment
             if (drawPoints.length > 0) {
                 const prevPoint = drawPoints[drawPoints.length - 1];

                 const segmentId = `line-${Date.now()}-${Math.random()}`;
                 const segmentShape: IShape = {
                    id: segmentId,
                    layerId: activeLayerId,
                    type: 'line',
                    points: [prevPoint, newPoint],
                    height: 0,
                    color: '#000000',
                    position: [0, 0, 0],
                    rotation: 0,
                    scale: [1, 1, 1],
                    name: 'Line'
                 };
                 addShape(segmentShape);
                 currentChainIds.current.push(segmentId);

                 // 4. Geometry Cutting (SketchUp-like behavior)
                 // Check if this new line segment "cuts" any existing Flat shape
                 const segmentStart = prevPoint;
                 const segmentEnd = newPoint;

                 // Copy existing flat shapes to avoid mutation issues during iteration
                 const flatShapes = shapes.filter(s => s.type === 'flat');

                 for (const shape of flatShapes) {
                    // Convert shape points to world coordinates to perform the cut check
                    const worldPoints = shape.points.map(p => {
                         const wp = transformPoint(p, shape);
                         return { x: wp.x, y: wp.y, z: wp.z };
                    });

                    // Simple height check: only cut if drawn roughly on the same plane (XZ projection for now)
                    // This assumes "Flat" shapes are generally planar.
                    const result = cutPolygonBySegment(worldPoints, segmentStart, segmentEnd);

                    if (result) {
                        const [polyA, polyB] = result;

                        // Create 2 new shapes replacing the old one
                        // We reset position to [0,0,0] because polyA/B are now World Coordinates
                        const shapeA: IShape = { 
                            ...shape, 
                            id: `split-${Date.now()}-A`, 
                            points: polyA, 
                            position: [0, 0, 0], 
                            rotation: 0, 
                            scale: [1, 1, 1],
                            name: `${shape.name} (1)`
                        };
                        const shapeB: IShape = { 
                            ...shape, 
                            id: `split-${Date.now()}-B`, 
                            points: polyB, 
                            position: [0, 0, 0], 
                            rotation: 0, 
                            scale: [1, 1, 1],
                            name: `${shape.name} (2)`
                        };

                        replaceShapes([shape.id], [shapeA, shapeB]);
                        // Continue loop in case it cuts multiple overlapping shapes
                    }
                 }
             }

         } else if (tool === ToolType.DRAW_RECT) {
             if (drawPoints.length === 0) {
                 setDrawPoints([newPoint]);
             } else {
                 const p1 = drawPoints[0];
                 const p2 = newPoint;
                 const minX = Math.min(p1.x, p2.x);
                 const maxX = Math.max(p1.x, p2.x);
                 const minZ = Math.min(p1.z, p2.z);
                 const maxZ = Math.max(p1.z, p2.z);
                 const corners: IPoint[] = [
                     { x: minX, y: 0, z: minZ },
                     { x: maxX, y: 0, z: minZ },
                     { x: maxX, y: 0, z: maxZ },
                     { x: minX, y: 0, z: maxZ },
                     { x: minX, y: 0, z: minZ },
                 ];
                 finishShape(corners, 'Room', p1.y); // Use start height
             }
         } else if (tool === ToolType.DRAW_CIRCLE) {
             if (drawPoints.length === 0) {
                 setDrawPoints([newPoint]);
             } else {
                 const center = drawPoints[0];
                 const radius = Math.sqrt((newPoint.x - center.x)**2 + (newPoint.z - center.z)**2);
                 if (radius > 0.01) {
                     const points = createCirclePoints(radius);
                     const shiftedPoints = points.map(p => ({ x: p.x + center.x, y: 0, z: p.z + center.z }));
                     finishShape(shiftedPoints, 'Circle', center.y);
                 } else {
                     setDrawPoints([]);
                 }
             }
         } else if (tool === ToolType.DRAW_ARC) {
              if (drawPoints.length === 0) {
                 setDrawPoints([newPoint]);
             } else {
                 const center = drawPoints[0];
                 const radius = Math.sqrt((newPoint.x - center.x)**2 + (newPoint.z - center.z)**2);
                 if (radius > 0.01) {
                     const points = createArcPoints(radius);
                     const shiftedPoints = points.map(p => ({ x: p.x + center.x, y: 0, z: p.z + center.z }));
                     finishShape(shiftedPoints, 'Arc', center.y);
                 } else {
                     setDrawPoints([]);
                 }
             }
         } else if (tool === ToolType.MEASURE) {
             if (drawPoints.length === 0) {
                 setDrawPoints([newPoint]);
             } else {
                 const p1 = drawPoints[0];
                 const p2 = newPoint;
                 const dimShape: IShape = {
                     id: `dim-${Date.now()}`,
                     layerId: 'layer-annotation',
                     type: 'dimension',
                     points: [p1, p2, {x: p1.x, y:0, z: p1.z}],
                     height: 0,
                     color: '#000000',
                     position: [0, 0, 0],
                     rotation: 0,
                     scale: [1, 1, 1],
                     name: 'Dimension'
                 };
                 addShape(dimShape);
                 setDrawPoints([]);
             }
         }
    };

    const finishShape = (points: IPoint[], namePrefix = 'Shape', elevationY?: number) => {
        // Determine elevation (Y) from points if not provided
        // Use average Y to handle slight snapping discrepancies, or just the first point
        const avgY = elevationY !== undefined ? elevationY : (points.reduce((sum, p) => sum + p.y, 0) / points.length);

        // Normalize points to be relative to the new position if needed, 
        // but since we are setting position to [0, avgY, 0], we can mostly keep X/Z as is 
        // because our rendering logic shifts by position.
        // However, standard ThreeJS shapes are local.
        // BUT our createThreeShape uses moveTo(p.x, -p.z).
        // If we set position to [0, avgY, 0], the points X/Z should be World X/Z.
        // This is consistent with how the app currently works (points are world-ish, position is offset).

        const shape: IShape = {
            id: `shape-${Date.now()}`,
            layerId: activeLayerId,
            type: 'flat',
            points: points,
            height: DEFAULT_HEIGHT,
            color: FLAT_COLOR,
            position: [0, avgY, 0],
            rotation: 0,
            scale: [1, 1, 1],
            name: `${namePrefix} ${Date.now().toString().slice(-4)}`
        };
        addShape(shape);
        setDrawPoints([]);
        currentChainIds.current = [];
    };

    const handlePointerDown = (e: ThreeEvent<PointerEvent>) => {
        if (e.button !== 0) return;
        setIsDragging(true);
        if (tool === ToolType.MEASURE && e.nativeEvent.ctrlKey && snapInfo?.type === 'edge' && snapInfo.snapEdge) {
             setGuideCreating({
                 active: true,
                 start: snapInfo.position.clone(),
                 current: snapInfo.position.clone(),
                 edge: snapInfo.snapEdge
             });
        }
    };

    const handlePointerUp = (e: ThreeEvent<PointerEvent>) => {
        setIsDragging(false);
        if (guideCreating.active) {
            if (guideCreating.edge) {
                const p1 = guideCreating.edge[0];
                const p2 = guideCreating.edge[1];
                const direction = new THREE.Vector3().subVectors(p2, p1).normalize();
                 const cursor = cursorPos;
                 const start = cursor.clone().sub(direction.clone().multiplyScalar(100));
                 const end = cursor.clone().add(direction.clone().multiplyScalar(100));
                 addGuideLine({
                     id: `guide-${Date.now()}`,
                     points: [[start.x, start.y, start.z], [end.x, end.y, end.z]]
                 });
            }
            setGuideCreating({ active: false, start: new THREE.Vector3(), current: new THREE.Vector3(), edge: null });
        }
    };

    const handleClick = (e: ThreeEvent<MouseEvent>) => {
        if (guideCreating.active) return;
        if (tool !== ToolType.SELECT && tool !== ToolType.PUSH_PULL) {
            const pos = snapInfo ? snapInfo.position : e.point;
            addPoint(pos);
        }
    };

    useEffect(() => {
        if (guideCreating.active) {
            setGuideCreating(prev => ({ ...prev, current: cursorPos }));
        }
    }, [cursorPos]);

    useEffect(() => {
        setDrawPoints([]);
        setTypedInput('');
        setInferenceGuide(null);
        currentChainIds.current = [];
    }, [tool]);

    return {
        drawPoints,
        cursorPos,
        setCursorPos,
        snapInfo,
        setSnapInfo,
        isDragging,
        handlePointerDown,
        handlePointerUp,
        handleClick,
        typedInput,
        guideCreating,
        inferenceGuide,
        setInferenceGuide
    };
};

// ... usePushPullManager, CameraHandler, EditorContent, Viewport ...
const usePushPullManager = () => {
    const { tool, updateShape, shapes, setMeasurement, formatValue, layers } = useApp();
    const { camera, gl } = useThree();
    const [ppState, setPPState] = useState<PushPullState>({
        mode: 'none', hoveredShapeId: null, hoveredEdgeIndex: -1, dragStartPoint: null, originalHeight: 0, originalPoints: [], normal: new THREE.Vector3(0, 1, 0), dragHeight: undefined
    });
    const [tempShape, setTempShapeState] = useState<IShape | null>(null);
    const tempShapeRef = useRef<IShape | null>(null);
    const setTempShape = (s: IShape | null) => { tempShapeRef.current = s; setTempShapeState(s); };
    const isDragging = !!ppState.dragStartPoint;

    const identifyFace = useCallback((e: ThreeEvent<PointerEvent>): Partial<PushPullState> | null => {
        const intersection = e.intersections.find(i => i.face && (i.object.userData?.isShape || i.object.parent?.userData?.isShape));
        if (!intersection || !intersection.face) return null;

        const object = intersection.object;
        let shapeId: string | null = null;
        if (object.userData?.isShape) shapeId = object.userData.id;
        else if (object.parent?.userData?.isShape) shapeId = object.parent.userData.id;
        if (!shapeId) return null;

        const shape = shapes.find(s => s.id === shapeId);
        if (!shape) return null;

        const layer = layers.find(l => l.id === shape.layerId);
        if (layer && !layer.visible) return null;

        const normalMatrix = new THREE.Matrix3().getNormalMatrix(object.matrixWorld);
        const worldNormal = intersection.face.normal.clone().applyMatrix3(normalMatrix).normalize();
        if (worldNormal.y > 0.9) return { mode: 'top', hoveredShapeId: shapeId, hoveredEdgeIndex: -1, normal: new THREE.Vector3(0, 1, 0) };
        if (worldNormal.y < -0.9) return { mode: 'none', hoveredShapeId: null, hoveredEdgeIndex: -1, normal: new THREE.Vector3(0, -1, 0) }; 

        if (Math.abs(worldNormal.y) < 0.2) {
            const hitPoint = intersection.point.clone().sub(new THREE.Vector3(...shape.position));
            const invRot = -shape.rotation;
            const xLocal = hitPoint.x * Math.cos(invRot) - hitPoint.z * Math.sin(invRot);
            const zLocal = hitPoint.x * Math.sin(invRot) + hitPoint.z * Math.cos(invRot);
            let closestIndex = -1;
            let minDistSq = Infinity;
            const pts = shape.points;
            for(let i=0; i<pts.length; i++) {
                const p1 = pts[i];
                const p2 = pts[(i+1) % pts.length];
                const unscaledX = xLocal / shape.scale[0];
                const unscaledZ = zLocal / shape.scale[2];
                const d2 = distToSegmentSquared(new THREE.Vector3(unscaledX, 0, unscaledZ), new THREE.Vector3(p1.x, 0, p1.z), new THREE.Vector3(p2.x, 0, p2.z));
                if (d2 < minDistSq) { minDistSq = d2; closestIndex = i; }
            }
            if (closestIndex !== -1) {
                const flatNormal = new THREE.Vector3(worldNormal.x, 0, worldNormal.z).normalize();
                return { mode: 'side', hoveredShapeId: shapeId, hoveredEdgeIndex: closestIndex, normal: flatNormal };
            }
        }
        return null;
    }, [shapes, layers]);

    const handlePointerMove = (e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL) return;
        if (isDragging) {
            e.stopPropagation();
            if (!ppState.dragStartPoint || !ppState.hoveredShapeId) return;
            const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
            if (!shape) return;
            const raycaster = new THREE.Raycaster();
            raycaster.setFromCamera(new THREE.Vector2((e.clientX / gl.domElement.clientWidth) * 2 - 1, -(e.clientY / gl.domElement.clientHeight) * 2 + 1), camera);
            if (ppState.mode === 'top') {
                const dragPlane = new THREE.Plane().setFromNormalAndCoplanarPoint(camera.getWorldDirection(new THREE.Vector3()).negate(), ppState.dragStartPoint);
                const target = new THREE.Vector3();
                raycaster.ray.intersectPlane(dragPlane, target);
                if (target) {
                    const deltaY = target.y - ppState.dragStartPoint.y;
                    const newHeight = Math.max(0.01, ppState.originalHeight + deltaY);
                    setPPState(prev => ({ ...prev, dragHeight: newHeight }));
                    setMeasurement(`高度: ${formatValue(newHeight)}`);
                }
            } else if (ppState.mode === 'side') {
                const dragPlane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0); 
                const target = new THREE.Vector3();
                raycaster.ray.intersectPlane(dragPlane, target);
                if (target) {
                    const diff = target.clone().sub(ppState.dragStartPoint);
                    const projection = diff.dot(ppState.normal);
                    const moveVectorWorld = ppState.normal.clone().multiplyScalar(projection);
                    setMeasurement(`偏移: ${formatValue(projection)}`);
                    const rot = -shape.rotation;
                    const dx = moveVectorWorld.x * Math.cos(rot) - moveVectorWorld.z * Math.sin(rot);
                    const dz = moveVectorWorld.x * Math.sin(rot) + moveVectorWorld.z * Math.cos(rot);
                    const dLocalX = dx / shape.scale[0];
                    const dLocalZ = dz / shape.scale[2];
                    const idx = ppState.hoveredEdgeIndex;
                    const newPoints = ppState.originalPoints.map(p => ({...p}));
                    const p1 = newPoints[idx];
                    const p2 = newPoints[(idx+1) % newPoints.length];
                    p1.x += dLocalX; p1.z += dLocalZ;
                    p2.x += dLocalX; p2.z += dLocalZ;
                    const updatedShape = { ...shape, points: newPoints };
                    setTempShape(updatedShape);
                }
            }
        } else {
            const res = identifyFace(e);
            if (res) {
                e.stopPropagation();
                document.body.style.cursor = res.mode === 'top' ? 'ns-resize' : 'ew-resize';
                setPPState(prev => ({ ...prev, mode: res.mode!, hoveredShapeId: res.hoveredShapeId!, hoveredEdgeIndex: res.hoveredEdgeIndex!, normal: res.normal! }));
            } else {
                setPPState(prev => ({ ...prev, mode: 'none', hoveredShapeId: null }));
                document.body.style.cursor = 'default';
            }
        }
    };
    const handlePointerDown = (e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL || e.button !== 0) return; 
        e.stopPropagation();
        if (ppState.mode !== 'none' && ppState.hoveredShapeId) {
             const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
             if(!shape) return;
             const raycaster = new THREE.Raycaster();
             raycaster.setFromCamera(new THREE.Vector2((e.clientX / gl.domElement.clientWidth) * 2 - 1, -(e.clientY / gl.domElement.clientHeight) * 2 + 1), camera);
             let startPoint = new THREE.Vector3();
             if (ppState.mode === 'top') {
                 const plane = new THREE.Plane().setFromNormalAndCoplanarPoint(camera.getWorldDirection(new THREE.Vector3()).negate(), e.point);
                 raycaster.ray.intersectPlane(plane, startPoint);
             } else {
                 const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
                 raycaster.ray.intersectPlane(plane, startPoint);
             }
             setPPState(prev => ({ ...prev, dragStartPoint: startPoint, originalHeight: shape.height, dragHeight: shape.height, originalPoints: JSON.parse(JSON.stringify(shape.points)) }));
             if (ppState.mode === 'side') setTempShape(shape);
        }
    };
    const handlePointerUp = useCallback(() => {
        if (ppState.mode === 'top' && ppState.dragHeight !== undefined && ppState.hoveredShapeId) {
             const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
             const updates: Partial<IShape> = { height: ppState.dragHeight };
             if (shape && shape.type === 'flat' && ppState.dragHeight > 0.05) {
                updates.type = 'solid';
                if (shape.color === FLAT_COLOR) updates.color = DEFAULT_COLOR;
             }
             updateShape(ppState.hoveredShapeId, updates);
        } else if (tempShapeRef.current) {
            updateShape(tempShapeRef.current.id, { points: tempShapeRef.current.points });
        }
        setTempShape(null);
        setPPState(prev => ({ ...prev, dragStartPoint: null, originalPoints: [], dragHeight: undefined }));
        setMeasurement('');
    }, [updateShape, ppState.mode, ppState.dragHeight, ppState.hoveredShapeId, shapes, setMeasurement]);
    useEffect(() => {
        if (isDragging) {
            const onGlobalPointerUp = () => handlePointerUp();
            window.addEventListener('pointerup', onGlobalPointerUp);
            return () => window.removeEventListener('pointerup', onGlobalPointerUp);
        }
    }, [isDragging, handlePointerUp]);
    return { ppState, handlePointerMove, handlePointerDown, handlePointerUp, isDragging, tempShape };
};

const CameraHandler: React.FC<{ view: string | null; onFinished: () => void }> = ({ view, onFinished }) => {
    const { camera, controls } = useThree();

    useEffect(() => {
        if (view) {
             const dist = 15;
             const pos = new THREE.Vector3();

             switch(view) {
                 case 'top': pos.set(0, dist, 0); break;
                 case 'bottom': pos.set(0, -dist, 0); break;
                 case 'left': pos.set(-dist, 5, 0); break;
                 case 'right': pos.set(dist, 5, 0); break;
                 case 'front': pos.set(0, 5, dist); break;
             }

             if (pos.lengthSq() > 0) {
                 camera.position.copy(pos);
                 camera.lookAt(0,0,0);
                 if (controls) {
                     // @ts-ignore
                     controls.target.set(0, 0, 0);
                     // @ts-ignore
                     controls.update();
                 }
             }
             onFinished();
        }
    }, [view, camera, controls, onFinished]);

    return null;
}

