const DimensionShape: React.FC<{ shape: IShape; isSelected: boolean; onSelect: (e: ThreeEvent<MouseEvent>) => void }> = ({ shape, isSelected, onSelect }) => {
    const { formatValue } = useApp();
    if (!shape.points || shape.points.length < 3) return null;
    const p1 = new THREE.Vector3(shape.points[0].x, shape.points[0].y, shape.points[0].z);
    const p2 = new THREE.Vector3(shape.points[1].x, shape.points[1].y, shape.points[1].z);
    const p3 = new THREE.Vector3(shape.points[2].x, shape.points[2].y, shape.points[2].z);
    const v12 = new THREE.Vector3().subVectors(p2, p1);
    const v13 = new THREE.Vector3().subVectors(p3, p1);
    const projection = v13.dot(v12) / v12.lengthSq();
    const projectedPoint = p1.clone().add(v12.multiplyScalar(projection));
    const offsetVector = new THREE.Vector3().subVectors(p3, projectedPoint);
    const dimStart = p1.clone().add(offsetVector);
    const dimEnd = p2.clone().add(offsetVector);
    const midPoint = new THREE.Vector3().addVectors(dimStart, dimEnd).multiplyScalar(0.5);
    const color = isSelected ? '#3b82f6' : '#333';
    return (
        <group onClick={(e) => { e.stopPropagation(); onSelect(e); }}>
            <SimpleLine points={[dimStart, dimEnd]} color={color} />
            <SimpleLine points={[p1, dimStart]} color="#999" dashed />
            <SimpleLine points={[p2, dimEnd]} color="#999" dashed />
            <mesh position={dimStart}><sphereGeometry args={[0.03]} /><meshBasicMaterial color={color} /></mesh>
            <mesh position={dimEnd}><sphereGeometry args={[0.03]} /><meshBasicMaterial color={color} /></mesh>
            <Billboard position={[midPoint.x, midPoint.y + 0.1, midPoint.z]}><Text fontSize={0.25} color={color} anchorX="center" anchorY="middle" outlineWidth={0.03} outlineColor="#ffffff" backgroundColor="#ffffff80" padding={0.05}>{formatValue(p1.distanceTo(p2))}</Text></Billboard>
        </group>
    );
};

const AlignmentLinesRenderer: React.FC<{ lines: AlignmentLine[] }> = ({ lines }) => {
    if (lines.length === 0) return null;
    return ( <group>{lines.map((line, i) => (<SimpleLine key={i} points={line} color="red" dashed lineWidth={2} depthTest={false} opacity={0.8} />))}</group> );
};

const SnapIndicator: React.FC<{ position: THREE.Vector3; type: SnapType; snapEdge?: [THREE.Vector3, THREE.Vector3] }> = ({ position, type, snapEdge }) => {
    if (type === 'grid' || type === 'none') return null;
    let color = '#f59e0b'; let size = 0.08; let geometry = <sphereGeometry args={[size]} />;
    if (type === 'endpoint' || type === 'vertex') { color = '#10b981'; size = 0.12; geometry = <sphereGeometry args={[size]} />; } 
    else if (type === 'midpoint') { color = '#06b6d4'; size = 0.1; geometry = <coneGeometry args={[size, size * 2, 4]} />; } 
    else if (type === 'edge') { color = '#ef4444'; size = 0.06; geometry = <boxGeometry args={[size * 1.5, size * 1.5, size * 1.5]} />; } 
    else if (type === 'face') { color = '#3b82f6'; }
    return (
        <group position={position}>
            {type === 'face' ? ( <mesh rotation={[-Math.PI/2, 0, 0]}><planeGeometry args={[0.2, 0.2]} /><meshBasicMaterial color={color} depthTest={false} transparent opacity={0.5} side={THREE.DoubleSide} /><lineSegments><edgesGeometry args={[new THREE.PlaneGeometry(0.2, 0.2)]} /><lineBasicMaterial color={color} depthTest={false} /></lineSegments></mesh> ) : ( <mesh>{geometry}<meshBasicMaterial color={color} depthTest={false} /></mesh> )}
            {type === 'edge' && snapEdge && (<SimpleLine points={[snapEdge[0], snapEdge[1]]} color="#ef4444" lineWidth={3} depthTest={false} />)}
            {type === 'midpoint' && snapEdge && (<SimpleLine points={[snapEdge[0], snapEdge[1]]} color="#06b6d4" lineWidth={3} depthTest={false} />)}
        </group>
    );
};

const CursorTooltip: React.FC<{ text: string; position: THREE.Vector3; type?: SnapType }> = ({ text, position, type }) => {
    if (type === 'grid' || type === 'none') return null;
    let displayType = ''; let bgColor = 'bg-slate-900/80'; let textColor = 'text-white';
    switch(type) {
        case 'vertex': displayType = '節點 (Node)'; bgColor = 'bg-emerald-600'; break;
        case 'endpoint': displayType = '端點 (Endpoint)'; bgColor = 'bg-emerald-600'; break;
        case 'midpoint': displayType = '中點 (Midpoint)'; bgColor = 'bg-cyan-600'; break;
        case 'edge': displayType = '邊緣 (Edge)'; bgColor = 'bg-red-500'; break;
        case 'face': displayType = '表面 (Face)'; bgColor = 'bg-blue-600'; break;
        case 'align': displayType = '對齊 (Align)'; bgColor = 'bg-pink-500'; break;
        default: displayType = '';
    }
    const displayText = displayType ? (text ? `${displayType}: ${text}` : displayType) : text;
    return (
        <Html position={[position.x, position.y + 0.5, position.z]} center style={{ pointerEvents: 'none', zIndex: 100 }}>
            <div className={`${bgColor} ${textColor} text-xs px-3 py-1.5 rounded-full shadow-lg backdrop-blur-sm border border-white/20 whitespace-nowrap flex items-center gap-2 font-bold transform -translate-y-2`}>{displayText}</div>
        </Html>
    );
};

interface BoxSelectionState {
    start: { x: number; y: number };
    end: { x: number; y: number };
    isSelecting: boolean;
}

const useBoxSelection = ({ onBoxChange }: { onBoxChange: (box: { left: number, top: number, width: number, height: number } | null) => void }) => {
    const { tool, selectShapes, shapes, layers, deselectAll } = useApp();
    const { gl, camera } = useThree();
    const [isSelecting, setIsSelecting] = useState(false);
    const startRef = useRef<{ x: number, y: number }>({ x: 0, y: 0 });

    useEffect(() => {
        if (!isSelecting) return;

        const updateBox = (e: PointerEvent) => {
            const rect = gl.domElement.getBoundingClientRect();
            const currentX = e.clientX - rect.left;
            const currentY = e.clientY - rect.top;

            const left = Math.min(startRef.current.x, currentX);
            const top = Math.min(startRef.current.y, currentY);
            const width = Math.abs(currentX - startRef.current.x);
            const height = Math.abs(currentY - startRef.current.y);

            onBoxChange({ left, top, width, height });
        };

        const onPointerMove = (e: PointerEvent) => updateBox(e);

        const onPointerUp = (e: PointerEvent) => {
            const rect = gl.domElement.getBoundingClientRect();
            const endX = e.clientX - rect.left;
            const endY = e.clientY - rect.top;
            const startX = startRef.current.x;
            const startY = startRef.current.y;
            const minX = Math.min(startX, endX); const maxX = Math.max(startX, endX);
            const minY = Math.min(startY, endY); const maxY = Math.max(startY, endY);

            if (Math.abs(maxX - minX) > 5 && Math.abs(maxY - minY) > 5) {
                const idsToSelect: string[] = [];
                shapes.forEach(shape => {
                    const layer = layers.find(l => l.id === shape.layerId);
                    if (layer && !layer.visible) return;
                    const pos = new THREE.Vector3(...shape.position);
                    pos.project(camera);
                    const x = (pos.x * 0.5 + 0.5) * rect.width;
                    const y = (-(pos.y * 0.5) + 0.5) * rect.height;
                    if (x >= minX && x <= maxX && y >= minY && y <= maxY) idsToSelect.push(shape.id);
                });
                selectShapes(idsToSelect);
            } else {
                if (tool === ToolType.SELECT && !e.ctrlKey) deselectAll();
            }

            setIsSelecting(false);
            onBoxChange(null);
        };

        window.addEventListener('pointermove', onPointerMove);
        window.addEventListener('pointerup', onPointerUp);
        return () => { 
            window.removeEventListener('pointermove', onPointerMove); 
            window.removeEventListener('pointerup', onPointerUp); 
        };
    }, [isSelecting, gl, camera, shapes, layers, selectShapes, deselectAll, tool, onBoxChange]);

    const onPointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.SELECT || e.button !== 0) return;
        const nE = e.nativeEvent;
        const rect = gl.domElement.getBoundingClientRect();
        const x = nE.clientX - rect.left;
        const y = nE.clientY - rect.top;

        startRef.current = { x, y };
        setIsSelecting(true);
        onBoxChange({ left: x, top: y, width: 0, height: 0 });
    }, [tool, gl, onBoxChange]);

    return { onPointerDown, isSelecting };
};

const useShapeDrag = (
    shape: IShape,
    shapes: IShape[],
    isSelected: boolean,
    tool: ToolType,
    updateShapes: (updates: { id: string; changes: Partial<IShape> }[]) => void,
    setDraggingState: (isDragging: boolean) => void,
    selectedIds: string[],
    shapeRefs: React.MutableRefObject<Record<string, THREE.Group | null>>,
    setAlignmentLines: (lines: AlignmentLine[]) => void
) => {
    const { camera, gl } = useThree();
    const groupRef = useRef<THREE.Group>(null);
    const dragInfo = useRef({ startPoint: new THREE.Vector3(), originalPositions: {} as Record<string, THREE.Vector3>, isDragging: false });
    const getGroundIntersection = (clientX: number, clientY: number) => {
        const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
        const raycaster = new THREE.Raycaster();
        const ndc = new THREE.Vector2((clientX / gl.domElement.clientWidth) * 2 - 1, -(clientY / gl.domElement.clientHeight) * 2 + 1);
        raycaster.setFromCamera(ndc, camera);
        const target = new THREE.Vector3();
        const hit = raycaster.ray.intersectPlane(plane, target);
        return hit ? target : null;
    };
    const handlePointerMove = useCallback((e: PointerEvent) => {
        if (!dragInfo.current.isDragging) return;
        const intersect = getGroundIntersection(e.clientX, e.clientY);
        if (intersect) {
             const rawDelta = new THREE.Vector3().subVectors(intersect, dragInfo.current.startPoint);
             const myOriginalPos = dragInfo.current.originalPositions[shape.id];
             if (!myOriginalPos) return;
             const targetPos = new THREE.Vector3().addVectors(myOriginalPos, rawDelta);
             let snappedX = Math.round(targetPos.x / SNAP_GRID) * SNAP_GRID;
             let snappedZ = Math.round(targetPos.z / SNAP_GRID) * SNAP_GRID;
             const newLines: AlignmentLine[] = [];
             const myBoundsRaw = getShapeBounds(shape, new THREE.Vector3(targetPos.x, myOriginalPos.y, targetPos.z));
             let bestXDist = 0.3; let bestXVal: number | null = null; let xMatchLine: AlignmentLine | null = null;
             let bestZDist = 0.3; let bestZVal: number | null = null; let zMatchLine: AlignmentLine | null = null;
             for (const other of shapes) {
                 if (selectedIds.includes(other.id)) continue;
                 const otherBounds = getShapeBounds(other);
                 const xSources = [myBoundsRaw.centerX, myBoundsRaw.minX, myBoundsRaw.maxX];
                 const xTargets = [otherBounds.centerX, otherBounds.minX, otherBounds.maxX];
                 for (const src of xSources) {
                     for (const tgt of xTargets) {
                         const dist = Math.abs(src - tgt);
                         if (dist < bestXDist) { bestXDist = dist; bestXVal = targetPos.x - (src - tgt); const minZ = Math.min(myBoundsRaw.minZ, otherBounds.minZ) - 1; const maxZ = Math.max(myBoundsRaw.maxZ, otherBounds.maxZ) + 1; xMatchLine = [ new THREE.Vector3(tgt, 0, minZ), new THREE.Vector3(tgt, 0, maxZ) ]; }
                     }
                 }
                 const zSources = [myBoundsRaw.centerZ, myBoundsRaw.minZ, myBoundsRaw.maxZ];
                 const zTargets = [otherBounds.centerZ, otherBounds.minZ, otherBounds.maxZ];
                 for (const src of zSources) {
                     for (const tgt of zTargets) {
                         const dist = Math.abs(src - tgt);
                         if (dist < bestZDist) { bestZDist = dist; bestZVal = targetPos.z - (src - tgt); const minX = Math.min(myBoundsRaw.minX, otherBounds.minX) - 1; const maxX = Math.max(myBoundsRaw.maxX, otherBounds.maxX) + 1; zMatchLine = [ new THREE.Vector3(minX, 0, tgt), new THREE.Vector3(maxX, 0, tgt) ]; }
                     }
                 }
             }
             if (bestXVal !== null) { snappedX = bestXVal; if (xMatchLine) newLines.push(xMatchLine); }
             if (bestZVal !== null) { snappedZ = bestZVal; if (zMatchLine) newLines.push(zMatchLine); }
             setAlignmentLines(newLines);
             const snappedPos = new THREE.Vector3(snappedX, myOriginalPos.y, snappedZ);
             const effectiveDelta = new THREE.Vector3().subVectors(snappedPos, myOriginalPos);
             Object.entries(dragInfo.current.originalPositions).forEach(([id, origPos]) => {
                 const ref = shapeRefs.current[id];
                 if (ref) { ref.position.copy(origPos).add(effectiveDelta); }
             });
        }
    }, [camera, gl, shape.id, shapes, selectedIds]);
    const handlePointerUp = useCallback((e: PointerEvent) => {
        if (!dragInfo.current.isDragging) return;
        document.body.style.cursor = 'default';
        dragInfo.current.isDragging = false;
        setDraggingState(false);
        setAlignmentLines([]);
        window.removeEventListener('pointermove', handlePointerMove);
        window.removeEventListener('pointerup', handlePointerUp);
        const updates = Object.keys(dragInfo.current.originalPositions).map(id => {
            const ref = shapeRefs.current[id];
            if (ref) { return { id, changes: { position: [ref.position.x, ref.position.y, ref.position.z] as [number, number, number] } }; }
            return null;
        }).filter(Boolean) as { id: string, changes: Partial<IShape> }[];
        if (updates.length > 0) updateShapes(updates);
    }, [handlePointerMove, updateShapes, setDraggingState, setAlignmentLines]);
    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.SELECT || e.button !== 0) return;
        e.stopPropagation();
        const intersect = getGroundIntersection(e.clientX, e.clientY);
        if (intersect && groupRef.current) {
            dragInfo.current.isDragging = true;
            dragInfo.current.startPoint.copy(intersect);
            let idsToMove: string[] = [];
            if (isSelected) idsToMove = [...selectedIds]; else { if (shape.groupId) idsToMove = shapes.filter(s => s.groupId === shape.groupId).map(s => s.id); else idsToMove = [shape.id]; }
            if (!idsToMove.includes(shape.id)) idsToMove.push(shape.id);
            const origins: Record<string, THREE.Vector3> = {};
            idsToMove.forEach(id => { const ref = shapeRefs.current[id]; if (ref) origins[id] = ref.position.clone(); });
            dragInfo.current.originalPositions = origins;
            document.body.style.cursor = 'move';
            setDraggingState(true);
            window.addEventListener('pointermove', handlePointerMove);
            window.addEventListener('pointerup', handlePointerUp);
        }
    }, [tool, shape, shapes, camera, gl, handlePointerMove, handlePointerUp, setDraggingState, isSelected, selectedIds]);
    useEffect(() => { return () => { window.removeEventListener('pointermove', handlePointerMove); window.removeEventListener('pointerup', handlePointerUp); }; }, [handlePointerMove, handlePointerUp]);
    return { groupRef, handlePointerDown };
};

const ShapeRenderer = React.memo(({ shape, isSelected, pushPullState, pushPullHandlers, drawingHandlers, rotateHandlers, setDraggingState, onShapeRef, shapeRefs, setAlignmentLines }: ShapeRendererProps) => {
    const { unit, tool, updateShapes, layers, selectedIds, shapes, selectShape, updateShape } = useApp();
    const parentLayer = layers.find(l => l.id === shape.layerId);

    const handleSelect = useCallback((e: ThreeEvent<MouseEvent>) => {
        e.stopPropagation();
        const isMulti = e.nativeEvent.ctrlKey || e.nativeEvent.metaKey;
        selectShape(shape.id, isMulti);
    }, [selectShape, shape.id]);

    const dimensionSelect = useCallback((e: ThreeEvent<MouseEvent>) => {
        if (!isSelected) {
             e.stopPropagation();
             selectShape(shape.id, e.nativeEvent.ctrlKey || e.nativeEvent.metaKey);
        }
    }, [isSelected, selectShape, shape.id]);

    if (parentLayer && !parentLayer.visible) return null;

    if (shape.type === 'dimension') { 
        return <DimensionShape shape={shape} isSelected={isSelected} onSelect={dimensionSelect} />; 
    }

    // Render Line Types specifically
    if (shape.type === 'line') {
         if (shape.points.length < 2) return null;
         const p1 = transformPoint(shape.points[0], shape);
         const p2 = transformPoint(shape.points[1], shape);
         return (
             <group 
                position={[0, 0, 0]} // Lines are drawn in world space logic usually, or local. We will use transformPoint above which applies pos/rot.
                onClick={(e) => { 
                    if (tool === ToolType.SELECT) handleSelect(e);
                }}
             >
                <SimpleLine points={[p1, p2]} color={isSelected ? '#3b82f6' : 'black'} lineWidth={2} />
             </group>
         );
    }

    const isPushPullMode = tool === ToolType.PUSH_PULL;
    const highlightColor = shape.color;
    const edgeColor = isSelected ? '#3b82f6' : '#333';
    const emissiveColor = isSelected ? '#3b82f6' : '#000000';
    const emissiveIntensity = isSelected ? 0.2 : 0;

    const { groupRef, handlePointerDown } = useShapeDrag(shape, shapes, isSelected, tool, updateShapes, setDraggingState, selectedIds, shapeRefs, setAlignmentLines);

    useLayoutEffect(() => { 
        onShapeRef(shape.id, groupRef.current); 
        return () => onShapeRef(shape.id, null); 
    }, [onShapeRef, shape.id]);

    const isDraggingTop = pushPullState.mode === 'top' && pushPullState.hoveredShapeId === shape.id && !!pushPullState.dragStartPoint;
    let scaleY = 1;
    if (isDraggingTop && pushPullState.dragHeight !== undefined && shape.height > 0) scaleY = pushPullState.dragHeight / shape.height;

    const shape2D = useMemo(() => createThreeShape(shape.points), [shape.points]);

    return (
        <group 
            ref={groupRef}
            position={[shape.position[0], shape.position[1], shape.position[2]]} 
            rotation={new THREE.Euler(...shape.rotation)} 
            scale={[shape.scale[0], shape.scale[1] * scaleY, shape.scale[2]]} 
            userData={{ isShape: true, id: shape.id, isContainer: true }} 
            name="shape_group" 
            onPointerDown={(e) => {
                if (isPushPullMode) pushPullHandlers.handlePointerDown(e);
                else if (tool === ToolType.SELECT) { if (!isSelected) handleSelect(e); handlePointerDown(e); }
                else if (tool === ToolType.ROTATE) rotateHandlers.handleClick(e);
                else drawingHandlers.handlePointerDown(e);
            }}
            onPointerMove={(e) => { if (isPushPullMode) pushPullHandlers.handlePointerMove(e); }}
            onPointerUp={(e) => { if (isPushPullMode) pushPullHandlers.handlePointerUp(); else drawingHandlers.handlePointerUp(e); }}
        >
            <mesh rotation={[-Math.PI/2, 0, 0]} castShadow receiveShadow userData={{ isShape: true, id: shape.id }}>
                <extrudeGeometry args={[shape2D, { depth: shape.height, bevelEnabled: false }]} />
                <meshStandardMaterial color={highlightColor} emissive={emissiveColor} emissiveIntensity={emissiveIntensity} transparent={shape.type === 'flat'} opacity={shape.type === 'flat' ? 0.6 : 1.0} polygonOffset={shape.type === 'flat'} polygonOffsetFactor={shape.type === 'flat' ? -1 : 0} />
                <Edges color={edgeColor} threshold={15} renderOrder={1000} visible={!isPushPullMode} />
            </mesh>
        </group>
    );
});

// ... Gizmo & Helper Components ...
const SelectionGizmo: React.FC<{ setDragging: (active: boolean) => void }> = ({ setDragging }) => {
    const { selectedIds, transformMode, updateShape, tool } = useApp();
    const { scene, camera } = useThree();
    const [targetObj, setTargetObj] = useState<THREE.Object3D | null>(null);
    const isEnabled = (tool === ToolType.SELECT || tool === ToolType.ROTATE) && selectedIds.length === 1;
    const selectedId = isEnabled ? selectedIds[0] : null;
    const activeMode = tool === ToolType.ROTATE ? 'rotate' : transformMode;
    useFrame(() => {
        if (!isEnabled || !selectedId) { if (targetObj) setTargetObj(null); return; }
        if (targetObj && targetObj.userData?.id === selectedId) return;
        let found: THREE.Object3D | null = null;
        scene.traverse((child) => { if (found) return; if (child.userData?.isShape && child.userData?.id === selectedId && child.userData?.isContainer) found = child; });
        if (found && found !== targetObj) setTargetObj(found);
    });
    if (!isEnabled || !targetObj) return null;
    return ( 
        <TransformControls 
            object={targetObj} 
            mode={activeMode} 
            space={activeMode === 'scale' ? 'local' : 'world'} 
            onDraggingChange={(isDragging) => { setDragging(isDragging); }} 
            onMouseUp={() => { if (targetObj) updateShape(selectedId!, { position: [targetObj.position.x, targetObj.position.y, targetObj.position.z], rotation: [targetObj.rotation.x, targetObj.rotation.y, targetObj.rotation.z], scale: [targetObj.scale.x, targetObj.scale.y, targetObj.scale.z] }); }} 
        /> 
    );
};

const CameraHandler: React.FC<{ view: string | null; onFinished: () => void }> = ({ view, onFinished }) => {
    const { camera, controls } = useThree();
    useEffect(() => {
        if (!view) return;
        let targetPos = new THREE.Vector3();
        const DISTANCE = 20;
        switch (view) { case 'top': targetPos.set(0, DISTANCE, 0); break; case 'bottom': targetPos.set(0, -DISTANCE, 0); break; case 'front': targetPos.set(0, 0, DISTANCE); break; case 'back': targetPos.set(0, 0, -DISTANCE); break; case 'right': targetPos.set(DISTANCE, 0, 0); break; case 'left': targetPos.set(-DISTANCE, 0, 0); break; default: return; }
        camera.position.copy(targetPos);
        camera.lookAt(0, 0, 0);
        if (controls) { const c = controls as any; if (c.target && typeof c.target.set === 'function') { c.target.set(0, 0, 0); c.update(); } }
        onFinished();
    }, [view, camera, controls, onFinished]);
    return null;
};

// ... Interaction Layer ...
const DrawingPreview: React.FC<{ tool: ToolType; points: IPoint[]; cursorPos: THREE.Vector3; guideCreating: { active: boolean, start: THREE.Vector3, current: THREE.Vector3, edge: [THREE.Vector3, THREE.Vector3] | null }; drawingNormal: THREE.Vector3 }> = ({ tool, points, cursorPos, guideCreating, drawingNormal }) => {
    const { formatValue } = useApp();
    const currentPoint = cursorPos;
    if (tool === ToolType.MEASURE && guideCreating.active && guideCreating.edge) {
        const p1 = guideCreating.edge[0]; const p2 = guideCreating.edge[1];
        const direction = new THREE.Vector3().subVectors(p2, p1).normalize();
        const lineStart = guideCreating.current.clone().sub(direction.clone().multiplyScalar(100));
        const lineEnd = guideCreating.current.clone().add(direction.clone().multiplyScalar(100));
        const edgeVec = new THREE.Vector3().subVectors(p2, p1);
        const pointVec = new THREE.Vector3().subVectors(guideCreating.current, p1);
        const projected = p1.clone().add(edgeVec.clone().multiplyScalar(pointVec.dot(edgeVec) / edgeVec.lengthSq()));
        const dist = guideCreating.current.distanceTo(projected);
        return ( <group><SimpleLine points={[lineStart, lineEnd]} color="#a855f7" dashed opacity={0.6} /><Billboard position={[guideCreating.current.x, guideCreating.current.y + 0.2, guideCreating.current.z]}><Text fontSize={0.25} color="#a855f7" anchorX="center" anchorY="middle" outlineWidth={0.03} outlineColor="#fff" backgroundColor="#ffffff80" padding={0.05}>{formatValue(dist)}</Text></Billboard></group> );
    }
    if (points.length === 0) return null;
    const startPoint = points[points.length-1];
    const startVec = new THREE.Vector3(startPoint.x, startPoint.y, startPoint.z);

    if (tool === ToolType.DRAW_LINE) { 
        // Draw dashed line from LAST point to cursor
        return <SimpleLine points={[startVec, currentPoint]} color="black" dashed />; 
    }

    if (tool === ToolType.DRAW_RECT) {
        const start = points[0];
        const startV = new THREE.Vector3(start.x, start.y, start.z);
        const { right, top } = getLocalBasis(drawingNormal);
        const diff = new THREE.Vector3().subVectors(currentPoint, startV);
        const w = diff.dot(right); const h = diff.dot(top);
        const p1 = startV;
        const p2 = startV.clone().add(right.clone().multiplyScalar(w));
        const p3 = startV.clone().add(right.clone().multiplyScalar(w)).add(top.clone().multiplyScalar(h));
        const p4 = startV.clone().add(top.clone().multiplyScalar(h));
        const rectPoints = [p1, p2, p3, p4, p1];
        return <SimpleLine points={rectPoints} color="black" dashed />;
    }
    // ... Circle/Measure (omitted for brevity, same as before) ...
    return null;
};

const InteractionLayer: React.FC<{
    shapes: IShape[];
    tool: ToolType;
    setCursorPos: (v: THREE.Vector3) => void;
    setSnapInfo: (s: SnapResult | null) => void;
    cursorPos: THREE.Vector3;
    snapInfo: SnapResult | null;
    drawPoints: IPoint[];
    isDragging: boolean;
    drawingHeight: number;
    typedInput: string;
    guideCreating: any;
    rotateState: RotateState;
    drawingNormal: THREE.Vector3;
    isGizmoDragging: boolean;
    inferenceGuide: InferenceGuide | null;
    setInferenceGuide: (g: InferenceGuide | null) => void;
}> = ({ shapes, tool, setCursorPos, setSnapInfo, cursorPos, snapInfo, drawPoints, isDragging, drawingHeight, typedInput, guideCreating, rotateState, drawingNormal, isGizmoDragging, inferenceGuide, setInferenceGuide }) => {
    const { setMeasurement, formatValue, layers } = useApp();
    const updateMeasurement = useCallback((pos: THREE.Vector3, input?: string) => {
        let text = '';
        if (tool === ToolType.MEASURE && guideCreating.active && guideCreating.edge) {
             const p1 = guideCreating.edge[0]; const p2 = guideCreating.edge[1]; const edgeVec = new THREE.Vector3().subVectors(p2, p1); const pointVec = new THREE.Vector3().subVectors(pos, p1); const projected = p1.clone().add(edgeVec.clone().multiplyScalar(pointVec.dot(edgeVec) / edgeVec.lengthSq())); const dist = pos.distanceTo(projected); text = `偏移距離: ${formatValue(dist)}`;
        } else if (tool === ToolType.ROTATE) {
             text = '拖曳旋轉環進行旋轉';
        } else if (drawPoints.length > 0) {
            const start = drawPoints[drawPoints.length - 1]; const current = pos; const dist = Math.sqrt((current.x - start.x)**2 + (current.y - start.y)**2 + (current.z - start.z)**2);
            if (tool === ToolType.DRAW_LINE) text = `長度: ${input ? input : formatValue(dist)}`;
            else if (tool === ToolType.DRAW_RECT) text = input ? `寬度, 深度: ${input}` : `對角距離: ${formatValue(dist)}`;
            else if (tool === ToolType.DRAW_CIRCLE) text = `半徑: ${input ? input : formatValue(dist)}`;
            else if (tool === ToolType.MEASURE) text = `距離: ${input ? input : formatValue(dist)}`;
        } else {
             if ([ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE, ToolType.MEASURE].includes(tool)) text = `X ${formatValue(pos.x)}, Z ${formatValue(pos.z)}`;
        }
        if (input !== undefined) text += '|';
        setMeasurement(text);
    }, [drawPoints, tool, formatValue, setMeasurement, guideCreating, rotateState]);

    useEffect(() => { 
        if (tool === ToolType.ROTATE || isGizmoDragging) return;
        if (typedInput) updateMeasurement(cursorPos, typedInput); else updateMeasurement(cursorPos); 
    }, [typedInput, cursorPos, updateMeasurement, rotateState.phase, rotateState.lockedAxis, tool, isGizmoDragging]); 

    const onPointerMove = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL || tool === ToolType.ROTATE || isGizmoDragging) return;

        const intersectPoint = e.point; 
        if (isDragging && drawPoints.length > 0 && tool !== ToolType.DRAW_LINE) {
            const startPoint = new THREE.Vector3(drawPoints[0].x, drawPoints[0].y, drawPoints[0].z);
            const plane = new THREE.Plane().setFromNormalAndCoplanarPoint(drawingNormal, startPoint);
            const target = new THREE.Vector3();
            const hit = e.ray.intersectPlane(plane, target);
            if (hit) { setCursorPos(target); setSnapInfo(null); if (!typedInput) updateMeasurement(target); return; }
        }

        const shapeIntersections = e.intersections.filter(i => (i.object.userData?.isShape || i.object.parent?.userData?.isShape) && i.object !== e.object);
        const visibleIntersections = shapeIntersections.filter(i => { const obj = i.object; const shapeId = obj.userData?.id || obj.parent?.userData?.id; const shape = shapes.find(s => s.id === shapeId); if (!shape) return false; const layer = layers.find(l => l.id === shape.layerId); return layer ? layer.visible : true; });
        const topShapeIntersect = visibleIntersections.length > 0 ? visibleIntersections[0] : undefined;
        const visibleShapes = shapes.filter(s => { const layer = layers.find(l => l.id === s.layerId); return layer ? layer.visible : true; });
        const snap = getGeometrySnap(intersectPoint, e.ray, visibleShapes, drawPoints, SNAP_THRESHOLD, topShapeIntersect);

        // --- Axis Inference for Line Drawing ---
        let newInferenceGuide: InferenceGuide | null = null;
        if (tool === ToolType.DRAW_LINE && drawPoints.length > 0) {
            const lastPt = drawPoints[drawPoints.length - 1];
            // Don't infer if we snapped to existing geometry vertex/edge
            if (snap.type === 'grid' || snap.type === 'face' || snap.type === 'none') {
                 const dx = Math.abs(snap.position.x - lastPt.x);
                 const dz = Math.abs(snap.position.z - lastPt.z);

                 // Prioritize closest axis
                 if (dx < ALIGN_THRESHOLD && dx < dz) {
                     snap.position.x = lastPt.x; // Lock X
                     snap.type = 'align';
                     newInferenceGuide = { 
                        type: 'z', // Moving along Z axis
                        start: new THREE.Vector3(lastPt.x, lastPt.y, lastPt.z), 
                        end: new THREE.Vector3(lastPt.x, snap.position.y, snap.position.z + (snap.position.z > lastPt.z ? 100 : -100)) 
                     };
                 } else if (dz < ALIGN_THRESHOLD) {
                     snap.position.z = lastPt.z; // Lock Z
                     snap.type = 'align';
                     newInferenceGuide = { 
                        type: 'x', // Moving along X axis
                        start: new THREE.Vector3(lastPt.x, lastPt.y, lastPt.z), 
                        end: new THREE.Vector3(snap.position.x + (snap.position.x > lastPt.x ? 100 : -100), snap.position.y, lastPt.z) 
                     };
                 }
            }
        }
        setInferenceGuide(newInferenceGuide);
        setCursorPos(snap.position); setSnapInfo(snap); if (!typedInput) updateMeasurement(snap.position);
    }, [tool, shapes, layers, drawPoints, setCursorPos, setSnapInfo, updateMeasurement, typedInput, isDragging, drawingNormal, isGizmoDragging, setInferenceGuide]);

    if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return null;
    return (
        <group>
            <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 0.005, 0]} onPointerMove={onPointerMove}>
                <planeGeometry args={[1000, 1000]} />
                <meshBasicMaterial visible={false} />
            </mesh>
             {snapInfo && tool !== ToolType.ROTATE && !isGizmoDragging && ( <><SnapIndicator position={snapInfo.position} type={snapInfo.type} snapEdge={snapInfo.snapEdge} /><CursorTooltip text={snapInfo.type === 'none' ? '' : snapInfo.type} position={snapInfo.position} type={snapInfo.type} /></> )}
             <InferenceGuideRenderer guide={inferenceGuide} />
             <DrawingPreview tool={tool} points={drawPoints} cursorPos={cursorPos} guideCreating={guideCreating} drawingNormal={drawingNormal} />
        </group>
    );
};

// ... Managers ...
const usePushPullManager = () => {
    // ... (No changes to push pull manager) ...
    const { tool, updateShape, shapes, setMeasurement, formatValue, layers } = useApp();
    const { camera, gl } = useThree();
    const [ppState, setPPState] = useState<PushPullState>({ mode: 'none', hoveredShapeId: null, hoveredEdgeIndex: -1, dragStartPoint: null, originalHeight: 0, originalPoints: [], normal: new THREE.Vector3(0, 1, 0), dragHeight: undefined });
    const [tempShape, setTempShapeState] = useState<IShape | null>(null);
    const tempShapeRef = useRef<IShape | null>(null);
    const setTempShape = (s: IShape | null) => { tempShapeRef.current = s; setTempShapeState(s); };
    const isDragging = !!ppState.dragStartPoint;
    const identifyFace = useCallback((e: ThreeEvent<PointerEvent>): Partial<PushPullState> | null => {
        const intersection = e.intersections.find(i => i.face && (i.object.userData?.isShape || i.object.parent?.userData?.isShape));
        if (!intersection || !intersection.face) return null;
        const object = intersection.object;
        let shapeId: string | null = null;
        if (object.userData?.isShape) shapeId = object.userData.id; else if (object.parent?.userData?.isShape) shapeId = object.parent.userData.id;
        if (!shapeId) return null;
        const shape = shapes.find(s => s.id === shapeId);
        if (!shape) return null;
        const layer = layers.find(l => l.id === shape.layerId);
        if (layer && !layer.visible) return null;
        const normalMatrix = new THREE.Matrix3().getNormalMatrix(object.matrixWorld);
        const worldNormal = intersection.face.normal.clone().applyMatrix3(normalMatrix).normalize();
        if (worldNormal.y > 0.9) return { mode: 'top', hoveredShapeId: shapeId, hoveredEdgeIndex: -1, normal: new THREE.Vector3(0, 1, 0) };
        if (worldNormal.y < -0.9) return { mode: 'none', hoveredShapeId: null, hoveredEdgeIndex: -1, normal: new THREE.Vector3(0, -1, 0) }; 
        if (Math.abs(worldNormal.y) < 0.2) {
            const hitPoint = intersection.point.clone().sub(new THREE.Vector3(...shape.position));
            const shapeQuat = new THREE.Quaternion().setFromEuler(new THREE.Euler(...shape.rotation));
            const invQuat = shapeQuat.clone().invert();
            const localPoint = hitPoint.applyQuaternion(invQuat);
            const xLocal = localPoint.x; const zLocal = localPoint.z;
            let closestIndex = -1; let minDistSq = Infinity;
            const pts = shape.points;
            for(let i=0; i<pts.length; i++) { const p1 = pts[i]; const p2 = pts[(i+1) % pts.length]; const unscaledX = xLocal / shape.scale[0]; const unscaledZ = zLocal / shape.scale[2]; const d2 = distToSegmentSquared(new THREE.Vector3(unscaledX, 0, unscaledZ), new THREE.Vector3(p1.x, 0, p1.z), new THREE.Vector3(p2.x, 0, p2.z)); if (d2 < minDistSq) { minDistSq = d2; closestIndex = i; } }
            if (closestIndex !== -1) { const flatNormal = new THREE.Vector3(worldNormal.x, 0, worldNormal.z).normalize(); return { mode: 'side', hoveredShapeId: shapeId, hoveredEdgeIndex: closestIndex, normal: flatNormal }; }
        }
        return null;
    }, [shapes, layers]);
    const handlePointerMove = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL) return;
        if (isDragging) {
            e.stopPropagation();
            if (!ppState.dragStartPoint || !ppState.hoveredShapeId) return;
            const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
            if (!shape) return;
            const raycaster = new THREE.Raycaster();
            raycaster.setFromCamera(new THREE.Vector2((e.clientX / gl.domElement.clientWidth) * 2 - 1, -(e.clientY / gl.domElement.clientHeight) * 2 + 1), camera);
            if (ppState.mode === 'top') { const dragPlane = new THREE.Plane().setFromNormalAndCoplanarPoint(camera.getWorldDirection(new THREE.Vector3()).negate(), ppState.dragStartPoint); const target = new THREE.Vector3(); raycaster.ray.intersectPlane(dragPlane, target); if (target) { const deltaY = target.y - ppState.dragStartPoint.y; const newHeight = Math.max(0.01, ppState.originalHeight + deltaY); setPPState(prev => ({ ...prev, dragHeight: newHeight })); setMeasurement(`高度: ${formatValue(newHeight)}`); } } 
            else if (ppState.mode === 'side') { const dragPlane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0); const target = new THREE.Vector3(); raycaster.ray.intersectPlane(dragPlane, target); if (target) { const diff = target.clone().sub(ppState.dragStartPoint); const projection = diff.dot(ppState.normal); const moveVectorWorld = ppState.normal.clone().multiplyScalar(projection); setMeasurement(`偏移: ${formatValue(projection)}`); const shapeQuat = new THREE.Quaternion().setFromEuler(new THREE.Euler(...shape.rotation)); const invQuat = shapeQuat.clone().invert(); const moveVectorLocal = moveVectorWorld.clone().applyQuaternion(invQuat); const dLocalX = moveVectorLocal.x / shape.scale[0]; const dLocalZ = moveVectorLocal.z / shape.scale[2]; const idx = ppState.hoveredEdgeIndex; const newPoints = ppState.originalPoints.map(p => ({...p})); const p1 = newPoints[idx]; const p2 = newPoints[(idx+1) % newPoints.length]; p1.x += dLocalX; p1.z += dLocalZ; p2.x += dLocalX; p2.z += dLocalZ; const updatedShape = { ...shape, points: newPoints }; setTempShape(updatedShape); } }
        } else {
            const res = identifyFace(e);
            if (res) { e.stopPropagation(); document.body.style.cursor = res.mode === 'top' ? 'ns-resize' : 'ew-resize'; setPPState(prev => ({ ...prev, mode: res.mode!, hoveredShapeId: res.hoveredShapeId!, hoveredEdgeIndex: res.hoveredEdgeIndex!, normal: res.normal! })); } 
            else { setPPState(prev => ({ ...prev, mode: 'none', hoveredShapeId: null })); document.body.style.cursor = 'default'; }
        }
    }, [tool, isDragging, ppState, shapes, camera, gl, identifyFace, setMeasurement, formatValue]);
    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL || e.button !== 0) return; 
        e.stopPropagation();
        if (ppState.mode !== 'none' && ppState.hoveredShapeId) {
             const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
             if(!shape) return;
             const raycaster = new THREE.Raycaster();
             raycaster.setFromCamera(new THREE.Vector2((e.clientX / gl.domElement.clientWidth) * 2 - 1, -(e.clientY / gl.domElement.clientHeight) * 2 + 1), camera);
             let startPoint = new THREE.Vector3();
             if (ppState.mode === 'top') { const plane = new THREE.Plane().setFromNormalAndCoplanarPoint(camera.getWorldDirection(new THREE.Vector3()).negate(), e.point); raycaster.ray.intersectPlane(plane, startPoint); } 
             else { const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0); raycaster.ray.intersectPlane(plane, startPoint); }
             setPPState(prev => ({ ...prev, dragStartPoint: startPoint, originalHeight: shape.height, dragHeight: shape.height, originalPoints: JSON.parse(JSON.stringify(shape.points)) }));
             if (ppState.mode === 'side') setTempShape(shape);
        }
    }, [tool, ppState, shapes, camera, gl]);
    const handlePointerUp = useCallback(() => {
        if (ppState.mode === 'top' && ppState.dragHeight !== undefined && ppState.hoveredShapeId) { const shape = shapes.find(s => s.id === ppState.hoveredShapeId); const updates: Partial<IShape> = { height: ppState.dragHeight }; if (shape && shape.type === 'flat' && ppState.dragHeight > 0.05) { updates.type = 'solid'; if (shape.color === FLAT_COLOR) updates.color = DEFAULT_COLOR; } updateShape(ppState.hoveredShapeId, updates); } 
        else if (tempShapeRef.current) { updateShape(tempShapeRef.current.id, { points: tempShapeRef.current.points }); }
        setTempShape(null); setPPState(prev => ({ ...prev, dragStartPoint: null, originalPoints: [], dragHeight: undefined })); setMeasurement('');
    }, [updateShape, ppState.mode, ppState.dragHeight, ppState.hoveredShapeId, shapes, setMeasurement]);
    useEffect(() => { if (isDragging) { const onGlobalPointerUp = () => handlePointerUp(); window.addEventListener('pointerup', onGlobalPointerUp); return () => window.removeEventListener('pointerup', onGlobalPointerUp); } }, [isDragging, handlePointerUp]);
    return { ppState, handlePointerMove, handlePointerDown, handlePointerUp, isDragging, tempShape };
};

const useRotateManager = () => {
    const rotateState: RotateState = { phase: 'hover', pivot: null, axis: null, startVector: null, currentAngle: 0, initialTransforms: {}, lockedAxis: null };
    const handleRotateMove = useCallback((e: ThreeEvent<PointerEvent>) => {}, []);
    const handleClick = useCallback((e: ThreeEvent<MouseEvent>) => {}, []);
    return { rotateState, handleRotateMove, handleClick };
}

const useDrawingManager = () => {
    const { tool, addShape, shapes, wallThickness, setTool, replaceShapes, updateShape, setMeasurement, activeLayerId, addGuideLine, removeShape } = useApp();
    const [drawPoints, setDrawPoints] = useState<IPoint[]>([]);
    const [cursorPos, setCursorPos] = useState<THREE.Vector3>(new THREE.Vector3());
    const [snapInfo, setSnapInfo] = useState<SnapResult | null>(null);
    const [isDragging, setIsDragging] = useState(false);
    const [drawingHeight, setDrawingHeight] = useState(0);
    const [typedInput, setTypedInput] = useState('');
    const [drawingNormal, setDrawingNormal] = useState<THREE.Vector3>(new THREE.Vector3(0, 1, 0));
    const [guideCreation, setGuideCreation] = useState<{ active: boolean, start: THREE.Vector3, current: THREE.Vector3, edge: [THREE.Vector3, THREE.Vector3] | null }>({ active: false, start: new THREE.Vector3(), current: new THREE.Vector3(), edge: null });
    const [inferenceGuide, setInferenceGuide] = useState<InferenceGuide | null>(null);
    const currentChainIds = useRef<string[]>([]); // To track continuous lines

    useEffect(() => { 
        setDrawPoints([]); setSnapInfo(null); setIsDragging(false); setDrawingHeight(0); setMeasurement(''); setTypedInput(''); setGuideCreation({ active: false, start: new THREE.Vector3(), current: new THREE.Vector3(), edge: null }); setDrawingNormal(new THREE.Vector3(0, 1, 0)); setInferenceGuide(null); currentChainIds.current = [];
    }, [tool, setMeasurement]);

    // Perform Geometry Cut: Try to split existing shapes with a new segment
    const attemptGeometryCut = useCallback((p1: THREE.Vector3, p2: THREE.Vector3) => {
        let cutOccurred = false;
        // Transform to simple point structure for calculation
        const start = { x: p1.x, y: 0, z: p1.z };
        const end = { x: p2.x, y: 0, z: p2.z };

        const flatShapes = shapes.filter(s => (s.type === 'flat' || s.type === 'solid') && s.name !== 'Edge');
        const idsToRemove = new Set<string>();
        const shapesToAddList: IShape[] = [];

        for (const shape of flatShapes) {
             if (idsToRemove.has(shape.id)) continue;

             // Simple height check: roughly on same Y plane (within small margin)
             // Assumes shape.position[1] is the base height.
             if (Math.abs(shape.position[1] - p1.y) > 0.1) continue;

             const worldPoints = shape.points.map(p => {
                 const wp = transformPoint(p, shape);
                 return { x: wp.x, y: 0, z: wp.z };
             });

             const splitResult = cutPolygonBySegment(worldPoints, start, end);
             if (splitResult) {
                 const [polyA, polyB] = splitResult;

                 // Center the new shapes
                 const createFragment = (points: IPoint[], suffix: string) => {
                     let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
                     points.forEach(p => { if(p.x < minX) minX = p.x; if(p.x > maxX) maxX = p.x; if(p.z < minZ) minZ = p.z; if(p.z > maxZ) maxZ = p.z; });
                     const cx = (minX + maxX) / 2;
                     const cz = (minZ + maxZ) / 2;
                     const localPoints = points.map(p => ({ x: p.x - cx, y: 0, z: p.z - cz }));

                     return {
                         ...shape,
                         id: `split-${Date.now()}-${suffix}`,
                         points: localPoints,
                         position: [cx, shape.position[1], cz] as [number, number, number],
                         rotation: [0, 0, 0] as [number, number, number], // Reset rotation for simplified world-aligned fragments
                         scale: [1, 1, 1] as [number, number, number],
                         name: shape.name
                     };
                 };

                 shapesToAddList.push(createFragment(polyA, 'A'));
                 shapesToAddList.push(createFragment(polyB, 'B'));
                 idsToRemove.add(shape.id);
                 cutOccurred = true;
             }
        }

        if (cutOccurred) {
            replaceShapes(Array.from(idsToRemove), shapesToAddList);
        }
    }, [shapes, replaceShapes]);

    const addPoint = useCallback((point: THREE.Vector3) => {
        // 1. Loop Closure Check
        if (drawPoints.length > 0) {
            const start = drawPoints[0];
            const dist = point.distanceTo(new THREE.Vector3(start.x, start.y, start.z));

            if (dist < SNAP_THRESHOLD) {
                // Close loop -> Create Face
                const finalPoints = [...drawPoints];
                // Cleanup continuous line segments
                currentChainIds.current.forEach(id => removeShape(id));
                currentChainIds.current = [];

                // Create Face
                const createShapeObj = (base: Partial<IShape>): IShape => ({ ...base as IShape, layerId: activeLayerId });
                // Calculate centroid
                let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
                finalPoints.forEach(p => { if(p.x < minX) minX = p.x; if(p.x > maxX) maxX = p.x; if(p.z < minZ) minZ = p.z; if(p.z > maxZ) maxZ = p.z; });
                const cx = (minX + maxX) / 2; const cz = (minZ + maxZ) / 2;
                const localPoints = finalPoints.map(p => ({ x: p.x - cx, y: 0, z: p.z - cz }));

                const newFace = createShapeObj({
                    id: `face-${Date.now()}`,
                    type: 'flat',
                    name: 'Face',
                    points: localPoints,
                    height: DEFAULT_HEIGHT,
                    color: FLAT_COLOR,
                    position: [cx, finalPoints[0].y, cz],
                    rotation: [0, 0, 0],
                    scale: [1, 1, 1]
                });

                addShape(newFace);
                setDrawPoints([]);
                setMeasurement('已建立平面');
                return;
            }
        }

        // 2. Add Point to State
        const newPoint = { x: point.x, y: point.y, z: point.z };
        const newPointsList = [...drawPoints, newPoint];
        setDrawPoints(newPointsList);

        // 3. Continuous Line Creation (Arbitrary Lines) & Cutting
        if (tool === ToolType.DRAW_LINE && drawPoints.length > 0) {
            const prev = drawPoints[drawPoints.length - 1];
            const p1 = new THREE.Vector3(prev.x, prev.y, prev.z);
            const p2 = point;

            // Create "Edge" Shape immediately
            const createShapeObj = (base: Partial<IShape>): IShape => ({ ...base as IShape, layerId: activeLayerId });
            const localPoints = [{ x: 0, y: 0, z: 0 }, { x: 0, y: 0, z: 0 }]; // Placeholder, standard line doesn't use points array for geometry in same way, but let's stick to our type
            // Actually, for our renderer, we pass points relative to position.
            // Let's use simple world-space points inside the array and rely on renderer to handle it or use a specific line structure.
            // Our renderer uses: transformPoint. If shape.type === 'line', it draws segment.

            const lineId = `line-${Date.now()}-${Math.random()}`;
            const lineShape: IShape = {
                id: lineId,
                layerId: activeLayerId,
                type: 'line',
                name: 'Line',
                points: [{ x: 0, y: 0, z: 0 }, { x: p2.x - p1.x, y: p2.y - p1.y, z: p2.z - p1.z }], // Local coords relative to P1
                position: [p1.x, p1.y, p1.z],
                rotation: [0, 0, 0],
                scale: [1, 1, 1],
                height: 0,
                color: '#000000'
            };

            addShape(lineShape);
            currentChainIds.current.push(lineId);

            // 4. Geometry Cutting
            attemptGeometryCut(p1, p2);
        }

    }, [drawPoints, tool, activeLayerId, addShape, removeShape, attemptGeometryCut]);

    const finishShape = useCallback((finalPoints: IPoint[]) => {
        // This is mainly for Rect/Circle/etc. Line is handled in addPoint now.
        if (tool === ToolType.DRAW_LINE) {
            setDrawPoints([]);
            return;
        }

        const createShapeObj = (base: Partial<IShape>): IShape => ({ ...base as IShape, layerId: activeLayerId });
        const { right, top, normal } = getLocalBasis(drawingNormal);
        const rotationMatrix = new THREE.Matrix4().makeBasis(right, normal, top);
        const quaternion = new THREE.Quaternion().setFromRotationMatrix(rotationMatrix);
        const euler = new THREE.Euler().setFromQuaternion(quaternion);
        const startPoint = new THREE.Vector3(finalPoints[0].x, finalPoints[0].y, finalPoints[0].z);
        const newShapeBase: Partial<IShape> = { height: DEFAULT_HEIGHT, color: FLAT_COLOR, rotation: [euler.x, euler.y, euler.z], scale: [1, 1, 1] };
        let newShapePoints: IPoint[] = [];

        if (tool === ToolType.DRAW_RECT && finalPoints.length >= 2) {
             const endPoint = new THREE.Vector3(finalPoints[finalPoints.length - 1].x, finalPoints[finalPoints.length - 1].y, finalPoints[finalPoints.length - 1].z);
             const diff = new THREE.Vector3().subVectors(endPoint, startPoint);
             const width = diff.dot(right); const depth = diff.dot(top);
             if (Math.abs(width) >= 0.01 && Math.abs(depth) >= 0.01) {
                 const worldCenter = startPoint.clone().add(right.clone().multiplyScalar(width / 2)).add(top.clone().multiplyScalar(depth / 2));
                 const halfW = Math.abs(width) / 2; const halfD = Math.abs(depth) / 2;
                 newShapePoints = [ { x: -halfW, y: 0, z: -halfD }, { x: halfW, y: 0, z: -halfD }, { x: halfW, y: 0, z: halfD }, { x: -halfW, y: 0, z: halfD }, { x: -halfW, y: 0, z: -halfD } ];
                 newShapeBase.id = `rect-${Date.now()}`; newShapeBase.type = 'flat'; newShapeBase.name = '矩形'; newShapeBase.position = [worldCenter.x, worldCenter.y, worldCenter.z];
             }
        } else if (tool === ToolType.DRAW_CIRCLE && finalPoints.length >= 2) {
            const endPoint = new THREE.Vector3(finalPoints[1].x, finalPoints[1].y, finalPoints[1].z);
            const radius = startPoint.distanceTo(endPoint);
            if (radius > 0.01) { newShapePoints = createCirclePoints(radius); newShapeBase.id = `circle-${Date.now()}`; newShapeBase.type = 'flat'; newShapeBase.name = '圓形'; newShapeBase.position = [startPoint.x, startPoint.y, startPoint.z]; }
        } else if (tool === ToolType.MEASURE && finalPoints.length >= 3) {
            newShapePoints = [finalPoints[0], finalPoints[1], finalPoints[2]]; newShapeBase.id = `dim-${Date.now()}`; newShapeBase.type = 'dimension'; newShapeBase.name = '尺寸標註'; newShapeBase.position = [0, 0, 0]; 
        }

        if (newShapePoints.length > 0) {
             const finalNewShape: IShape = createShapeObj({ ...newShapeBase as IShape, points: newShapePoints });
             addShape(finalNewShape);
        }

        setDrawPoints([]); 
        setTool(ToolType.SELECT); 
        setMeasurement(''); 
        setTypedInput('');

    }, [tool, addShape, activeLayerId, drawingNormal, setTool, setMeasurement]);

    const handleInputSubmit = useCallback(() => {
        if (!typedInput || drawPoints.length === 0) return;
        const start = drawPoints[drawPoints.length - 1]; const startVec = new THREE.Vector3(start.x, start.y, start.z); const cursorVec = cursorPos.clone();
        let targetVec = new THREE.Vector3(); const direction = cursorVec.clone().sub(startVec).normalize();
        if (tool === ToolType.DRAW_RECT) { const parts = typedInput.split(/[, ]+/).filter(p => p.trim() !== '').map(parseFloat); if (parts.length > 0 && !parts.some(isNaN)) { const val = parts[0]; targetVec = startVec.clone().add(direction.multiplyScalar(val)); } } 
        else { const val = parseFloat(typedInput); if (isNaN(val)) return; if (cursorVec.distanceTo(startVec) < 0.001) { direction.set(1, 0, 0); } targetVec = startVec.clone().add(direction.multiplyScalar(val)); }

        if (tool === ToolType.DRAW_LINE) {
            addPoint(targetVec);
            setTypedInput('');
        } else {
            const finalPoints = [...drawPoints, { x: targetVec.x, y: targetVec.y, z: targetVec.z }]; 
            finishShape(finalPoints);
        }
    }, [typedInput, drawPoints, cursorPos, tool, finishShape, addPoint]);

    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL || tool === ToolType.ROTATE) return;
        if (e.button !== 0) return;
        e.stopPropagation();
        setTypedInput('');
        const pt = snapInfo ? snapInfo.position.clone() : e.point.clone();
        setCursorPos(pt.clone());
        if (drawPoints.length === 0) { if (snapInfo && (snapInfo.type === 'face' || snapInfo.type === 'vertex' || snapInfo.type === 'edge') && snapInfo.normal) setDrawingNormal(snapInfo.normal.clone()); else setDrawingNormal(new THREE.Vector3(0, 1, 0)); }
        if (tool === ToolType.MEASURE && snapInfo && snapInfo.type === 'edge' && snapInfo.snapEdge) { setIsDragging(true); setGuideCreation({ active: true, start: pt.clone(), current: pt.clone(), edge: snapInfo.snapEdge }); return; }
        setIsDragging(true);

        if (tool === ToolType.DRAW_LINE) {
            addPoint(pt);
        } else {
            if (drawPoints.length === 0) { setDrawPoints([{ x: pt.x, y: pt.y, z: pt.z }]); if (tool === ToolType.DRAW_RECT || tool === ToolType.DRAW_CIRCLE) setDrawPoints(prev => [...prev, { x: pt.x, y: pt.y, z: pt.z }]); } 
            else if (tool === ToolType.MEASURE) setDrawPoints(prev => [...prev, { x: pt.x, y: pt.y, z: pt.z }]);
        }
    }, [tool, drawPoints, snapInfo, addPoint]);

    const handlePointerUp = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL || tool === ToolType.ROTATE) return;
        setIsDragging(false);
        if (tool === ToolType.MEASURE && guideCreation.active && guideCreation.edge) {
            const p1 = guideCreation.edge![0]; const p2 = guideCreation.edge![1]; const direction = new THREE.Vector3().subVectors(p2, p1).normalize();
            const lineStart = guideCreation.current.clone().sub(direction.clone().multiplyScalar(100)); const lineEnd = guideCreation.current.clone().add(direction.clone().multiplyScalar(100));
            addGuideLine({ id: `guide-${Date.now()}`, points: [ [lineStart.x, lineStart.y, lineStart.z], [lineEnd.x, lineEnd.y, lineEnd.z] ] });
            setGuideCreation({ active: false, start: new THREE.Vector3(), current: new THREE.Vector3(), edge: null }); setMeasurement(''); return;
        }
        if (tool === ToolType.MEASURE) { if (drawPoints.length >= 3) finishShape([...drawPoints]); return; }
        // For Rect/Circle, finish on Up
        if ((tool === ToolType.DRAW_RECT || tool === ToolType.DRAW_CIRCLE) && drawPoints.length >= 2) { const points = [...drawPoints]; points[points.length-1] = { x: cursorPos.x, y: cursorPos.y, z: cursorPos.z }; finishShape(points); }
    }, [tool, drawPoints, cursorPos, finishShape, guideCreation, addGuideLine, setMeasurement]);

    useEffect(() => { if (guideCreation.active) setGuideCreation(prev => ({ ...prev, current: cursorPos.clone() })); }, [cursorPos, guideCreation.active]);
    const handleClick = useCallback((e: ThreeEvent<MouseEvent>) => {}, []);

    // Esc Key Handling
    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
             if ([ToolType.SELECT, ToolType.PUSH_PULL, ToolType.ROTATE].includes(tool)) return;
             if (e.key === 'Escape') { 
                 if (drawPoints.length > 0) {
                     // 1. Clear current drawing
                     setDrawPoints([]);
                     setTypedInput('');
                     // 2. Remove unfinished chain lines
                     currentChainIds.current.forEach(id => removeShape(id));
                     currentChainIds.current = [];
                     setMeasurement('已取消繪製');
                 } else {
                     // 3. Switch tool if idle
                     setTool(ToolType.SELECT); 
                     setMeasurement(''); 
                     setTypedInput(''); 
                     setDrawingNormal(new THREE.Vector3(0, 1, 0)); 
                 }
                 setGuideCreation({ active: false, start: new THREE.Vector3(), current: new THREE.Vector3(), edge: null });
                 setInferenceGuide(null);
                 return; 
             }
             if (drawPoints.length === 0) return; 
             if (e.key === 'Enter') { handleInputSubmit(); return; }
             if (e.key === 'Backspace') { setTypedInput(prev => prev.slice(0, -1)); return; }
             if (/^[0-9.,-]$/.test(e.key)) { setTypedInput(prev => prev + e.key); }
        };
        window.addEventListener('keydown', handleKeyDown); return () => window.removeEventListener('keydown', handleKeyDown);
    }, [tool, drawPoints, handleInputSubmit, setTool, setMeasurement, removeShape]);

    return { drawPoints, cursorPos, setCursorPos, snapInfo, setSnapInfo, isDragging, drawingHeight, handlePointerDown, handlePointerUp, handleClick, typedInput, guideCreating: guideCreation, drawingNormal, inferenceGuide, setInferenceGuide };
};

const MemoizedOrbitControls = React.memo(({ enabled }: { enabled: boolean }) => {
    return ( <OrbitControls makeDefault enabled={enabled} minDistance={2} maxDistance={50} dampingFactor={0.1} enableDamping={true} rotateSpeed={0.5} panSpeed={0.5} zoomSpeed={0.6} /> );
});

const EditorContent: React.FC<{ onSelectionBoxUpdate: (box: { left: number, top: number, width: number, height: number } | null) => void }> = ({ onSelectionBoxUpdate }) => {
  const { shapes, tool, selectedIds, selectShape, updateShapes, guideLines, currentView, setCurrentView } = useApp();
  const [alignmentLines, setAlignmentLines] = useState<AlignmentLine[]>([]);
  const shapeRefs = useRef<Record<string, THREE.Group | null>>({});
  const [isShapeDragging, setIsShapeDragging] = useState(false);
  const [isGizmoDragging, setIsGizmoDragging] = useState(false);

  const setShapeRef = useCallback((id: string, ref: THREE.Group | null) => { shapeRefs.current[id] = ref; }, []);

  const { ppState, handlePointerMove: handlePPMove, handlePointerDown: handlePPDown, handlePointerUp: handlePPUp, isDragging: isPPDragging } = usePushPullManager();
  const { rotateState, handleRotateMove, handleClick: handleRotateClick } = useRotateManager();
  const { drawPoints, cursorPos: drawCursorPos, setCursorPos: setDrawCursorPos, snapInfo: drawSnapInfo, setSnapInfo: setDrawSnapInfo, isDragging: isDrawDragging, handlePointerDown: handleDrawDown, handlePointerUp: handleDrawUp, handleClick: handleDrawClick, typedInput, guideCreating, drawingNormal, inferenceGuide, setInferenceGuide } = useDrawingManager();

  const { onPointerDown: onBoxDown, isSelecting } = useBoxSelection({ onBoxChange: onSelectionBoxUpdate });

  const isOrbitEnabled = !isGizmoDragging && !isSelecting && ((tool === ToolType.SELECT && !isShapeDragging) || (tool === ToolType.PUSH_PULL && !isPPDragging) || (tool === ToolType.ROTATE && rotateState.phase !== 'rotating') || (tool !== ToolType.SELECT && tool !== ToolType.PUSH_PULL && tool !== ToolType.ROTATE && !isDrawDragging));

  const pushPullHandlers = useMemo(() => ({
      handlePointerDown: handlePPDown,
      handlePointerUp: handlePPUp,
      handlePointerMove: handlePPMove
  }), [handlePPDown, handlePPUp, handlePPMove]);

  const drawingHandlers = useMemo(() => ({
      handlePointerDown: handleDrawDown,
      handlePointerUp: handleDrawUp,
      handleClick: handleDrawClick
  }), [handleDrawDown, handleDrawUp, handleDrawClick]);

  const rotateHandlers = useMemo(() => ({
      handleClick: handleRotateClick,
      handlePointerMove: handleRotateMove
  }), [handleRotateClick, handleRotateMove]);

  return (
    <>
        <ambientLight intensity={0.7} />
        <directionalLight position={[10, 20, 10]} intensity={1.2} castShadow shadow-mapSize={[2048, 2048]} />
        <Grid infiniteGrid fadeDistance={50} sectionColor="#cbd5e1" cellColor="#e2e8f0" sectionSize={1} cellSize={0.1} />
        <MemoizedOrbitControls enabled={isOrbitEnabled} />

        <group 
            onPointerDown={(e) => {
                if (tool === ToolType.ROTATE) handleRotateClick(e);
                else if (tool === ToolType.SELECT) { onBoxDown(e); selectShape('', false); }
                else if (tool !== ToolType.PUSH_PULL) handleDrawDown(e);
            }} 
            onPointerUp={(e) => { if (tool !== ToolType.SELECT && tool !== ToolType.PUSH_PULL && tool !== ToolType.ROTATE) handleDrawUp(e); if (tool === ToolType.PUSH_PULL) handlePPUp(); }}
            onPointerMove={(e) => { if (tool === ToolType.PUSH_PULL) handlePPMove(e); if (tool === ToolType.ROTATE) handleRotateMove(e); }}
        >
            <mesh rotation={[-Math.PI/2, 0, 0]} position={[0, -0.02, 0]} receiveShadow><planeGeometry args={[1000, 1000]} /><meshBasicMaterial visible={false} /></mesh>
        </group>

        <group>
          {shapes.map(shape => (
            <ShapeRenderer
              key={shape.id}
              shape={shape}
              isSelected={selectedIds.includes(shape.id)}
              pushPullState={ppState}
              pushPullHandlers={pushPullHandlers}
              drawingHandlers={drawingHandlers}
              rotateHandlers={rotateHandlers}
              setDraggingState={setIsShapeDragging}
              onShapeRef={setShapeRef}
              shapeRefs={shapeRefs}
              setAlignmentLines={setAlignmentLines}
            />
          ))}
        </group>

        <InteractionLayer shapes={shapes} tool={tool} setCursorPos={setDrawCursorPos} setSnapInfo={setDrawSnapInfo} cursorPos={drawCursorPos} snapInfo={drawSnapInfo} drawPoints={drawPoints} isDragging={isDrawDragging} drawingHeight={0} typedInput={typedInput} guideCreating={guideCreating} rotateState={rotateState} drawingNormal={drawingNormal} isGizmoDragging={isGizmoDragging} inferenceGuide={inferenceGuide} setInferenceGuide={setInferenceGuide} />

        <AlignmentLinesRenderer lines={alignmentLines} />
        <GuideLinesRenderer lines={guideLines} />
        <SelectionGizmo setDragging={setIsGizmoDragging} />

        <GizmoHelper alignment="bottom-left" margin={[80, 80]}><GizmoViewport axisColors={['#ef4444', '#22c55e', '#3b82f6']} labelColor="white" /></GizmoHelper>
        <CameraHandler view={currentView} onFinished={() => setCurrentView(null)} />
    </>
  );
};

const Viewport: React.FC = () => {
  const { tool, deselectAll } = useApp();
  const [selectionBox, setSelectionBox] = useState<{ left: number, top: number, width: number, height: number } | null>(null);

