const DimensionShape: React.FC<{ shape: IShape; isSelected: boolean; onSelect: (e: ThreeEvent<MouseEvent>) => void }> = ({ shape, isSelected, onSelect }) => {
    const { formatValue } = useApp();
    if (!shape.points || shape.points.length < 3) return null;
    const p1 = new THREE.Vector3(shape.points[0].x, shape.points[0].y, shape.points[0].z);
    const p2 = new THREE.Vector3(shape.points[1].x, shape.points[1].y, shape.points[1].z);
    const p3 = new THREE.Vector3(shape.points[2].x, shape.points[2].y, shape.points[2].z);
    const v12 = new THREE.Vector3().subVectors(p2, p1);
    const v13 = new THREE.Vector3().subVectors(p3, p1);
    const projection = v13.dot(v12) / v12.lengthSq();
    const projectedPoint = p1.clone().add(v12.multiplyScalar(projection));
    const offsetVector = new THREE.Vector3().subVectors(p3, projectedPoint);
    const dimStart = p1.clone().add(offsetVector);
    const dimEnd = p2.clone().add(offsetVector);
    const midPoint = new THREE.Vector3().addVectors(dimStart, dimEnd).multiplyScalar(0.5);
    const color = isSelected ? '#3b82f6' : '#333';
    return (
        <group onClick={(e) => { e.stopPropagation(); onSelect(e); }}>
            <SimpleLine points={[dimStart, dimEnd]} color={color} />
            <SimpleLine points={[p1, dimStart]} color="#999" dashed />
            <SimpleLine points={[p2, dimEnd]} color="#999" dashed />
            <mesh position={dimStart}><sphereGeometry args={[0.03]} /><meshBasicMaterial color={color} /></mesh>
            <mesh position={dimEnd}><sphereGeometry args={[0.03]} /><meshBasicMaterial color={color} /></mesh>
            <Billboard position={[midPoint.x, midPoint.y + 0.1, midPoint.z]}><Text fontSize={0.25} color={color} anchorX="center" anchorY="middle" outlineWidth={0.03} outlineColor="#ffffff" backgroundColor="#ffffff80" padding={0.05}>{formatValue(p1.distanceTo(p2))}</Text></Billboard>
        </group>
    );
};

const AlignmentLinesRenderer: React.FC<{ lines: AlignmentLine[] }> = ({ lines }) => {
    if (lines.length === 0) return null;
    return ( <group>{lines.map((line, i) => (<SimpleLine key={i} points={line} color="red" dashed lineWidth={2} depthTest={false} opacity={0.8} />))}</group> );
};

const SnapIndicator: React.FC<{ position: THREE.Vector3; type: SnapType; snapEdge?: [THREE.Vector3, THREE.Vector3] }> = ({ position, type, snapEdge }) => {
    if (type === 'grid' || type === 'none') return null;
    let color = '#f59e0b'; let size = 0.08; let geometry = <sphereGeometry args={[size]} />;
    if (type === 'endpoint' || type === 'vertex') { color = '#10b981'; size = 0.12; geometry = <sphereGeometry args={[size]} />; } 
    else if (type === 'midpoint') { color = '#06b6d4'; size = 0.1; geometry = <coneGeometry args={[size, size * 2, 4]} />; } 
    else if (type === 'edge') { color = '#ef4444'; size = 0.06; geometry = <boxGeometry args={[size * 1.5, size * 1.5, size * 1.5]} />; } 
    else if (type === 'face') { color = '#3b82f6'; }
    return (
        <group position={position}>
            {type === 'face' ? ( <mesh rotation={[-Math.PI/2, 0, 0]}><planeGeometry args={[0.2, 0.2]} /><meshBasicMaterial color={color} depthTest={false} transparent opacity={0.5} side={THREE.DoubleSide} /><lineSegments><edgesGeometry args={[new THREE.PlaneGeometry(0.2, 0.2)]} /><lineBasicMaterial color={color} depthTest={false} /></lineSegments></mesh> ) : ( <mesh>{geometry}<meshBasicMaterial color={color} depthTest={false} /></mesh> )}
            {type === 'edge' && snapEdge && (<SimpleLine points={[snapEdge[0], snapEdge[1]]} color="#ef4444" lineWidth={3} depthTest={false} />)}
            {type === 'midpoint' && snapEdge && (<SimpleLine points={[snapEdge[0], snapEdge[1]]} color="#06b6d4" lineWidth={3} depthTest={false} />)}
        </group>
    );
};

